const LAB_LESSONS=[{"group": 0, "template": 0, "id": "0-0", "title": "定长窗口 · 元音计数", "problem": "定长子串中元音的最大数目", "problemId": "1456", "url": "https://leetcode.cn/problems/maximum-number-of-vowels-in-a-substring-of-given-length/", "signal": "连续、长度恰好 k，窗口统计可以一进一出更新。", "naive": "枚举每个窗口再数元音是 O(nk)。相邻窗口只有两个位置不同，不必重数。", "invariant": "在更新答案时，count 恰好描述 s[r-k+1..r] 的元音数。", "frames": [{"action": "输入 abciiidef，k=3", "state": "窗口 abc / count=1 / best=1", "reason": "前两个字符还不足 k，不更新答案。", "visual": {"kind": "array", "cells": ["a", "b", "c", "i", "i", "i", "d", "e", "f"], "active": [0, 1, 2], "markers": {}, "caption": "高亮表示当前关注的区间或状态；下方数字为下标。"}}, {"action": "右移一格", "state": "窗口 bci / count=1 / best=1", "reason": "移出 a 的 1，加入 i 的 1。", "visual": {"kind": "array", "cells": ["a", "b", "c", "i", "i", "i", "d", "e", "f"], "active": [1, 2, 3], "markers": {}, "caption": "高亮表示当前关注的区间或状态；下方数字为下标。"}}, {"action": "再右移", "state": "窗口 cii / count=2 / best=2", "reason": "移出 b 的 0，加入 i 的 1。", "visual": {"kind": "array", "cells": ["a", "b", "c", "i", "i", "i", "d", "e", "f"], "active": [2, 3, 4], "markers": {}, "caption": "高亮表示当前关注的区间或状态；下方数字为下标。"}}, {"action": "到达全元音窗口", "state": "窗口 iii / count=3 / best=3", "reason": "窗口长度上界为 3，后续不可能超过 3。", "visual": {"kind": "array", "cells": ["a", "b", "c", "i", "i", "i", "d", "e", "f"], "active": [3, 4, 5], "markers": {}, "caption": "高亮表示当前关注的区间或状态；下方数字为下标。"}}], "codeNotes": ["count += vowel：新元素进入统计。", "r < k-1：窗口没有形成时跳过结算。", "先 best，再减左端：结算时不能少算一个元素。"], "trap": "若先移出再更新，s=aaa、k=3 会把答案算成 2。", "quiz": {"question": "把“元音最多”改成“长度 k 的最大元素和”，改哪里？", "options": ["把元音贡献换成字符位置对应的数值，维护 sum", "把循环改为二重循环", "只移动左端点"], "correct": 0, "why": "窗口结构不变，只替换加入、移出和答案的统计量。"}, "practice": [{"id": "643", "title": "子数组最大平均数 I", "url": "https://leetcode.cn/problems/maximum-average-subarray-i/", "hint": "把 count 改成窗口和，最后除以 k。"}, {"id": "1052", "title": "爱生气的书店老板", "url": "https://leetcode.cn/problems/grumpy-bookstore-owner/", "hint": "先统计不生气时的基础收益，窗口维护额外挽回的顾客。"}], "source": "https://leetcode.cn/discuss/post/0viNMK/", "code": "// 定长窗口 · 元音计数\n// 使用前提：s 为普通单字节字符串，1 ≤ k ≤ s.size()。\n// 状态 / 不变量：在更新答案时，count 恰好描述 s[r-k+1..r] 的元音数。\n// 复杂度：O(n) 时间 / O(1) 空间\n\nint maxVowels(const string& s, int k) {\n    auto vowel = [](char c) {\n        return c=='a'||c=='e'||c=='i'||c=='o'||c=='u';\n    };\n    int count=0, best=0;\n    for (int r=0; r<(int)s.size(); ++r) {\n        // 新字符的贡献进入窗口。\n        count += vowel(s[r]);\n        if (r < k-1) continue;\n        // 窗口长度已达到k，此时先结算答案。\n        best = max(best, count);\n        // 移出本窗口最左端，为下一次右移准备。\n        count -= vowel(s[r-k+1]);\n    }\n    return best;\n}", "contract": "s 为普通单字节字符串，1 ≤ k ≤ s.size()。", "cost": "O(n) 时间 / O(1) 空间"}, {"group": 0, "template": 1, "id": "0-1", "title": "不定长窗口 · 最长不重复", "problem": "无重复字符的最长子串", "problemId": "3", "url": "https://leetcode.cn/problems/longest-substring-without-repeating-characters/", "signal": "求最长连续片段；新增字符后能通过缩左端恢复合法。", "naive": "枚举子串检查重复最坏 O(n²) 以上。左端已经排除的位置无需重新考虑。", "invariant": "每次更新 best 前，窗口内每种字符最多出现一次。", "frames": [{"action": "输入 abba，加入 a", "state": "l=0 / 窗口 a / best=1", "reason": "计数由 0 变 1，仍合法。", "visual": {"kind": "array", "cells": ["a", "b", "b", "a"], "active": [0], "markers": {"0": "L=R"}, "caption": "高亮表示当前关注的区间或状态；下方数字为下标。"}}, {"action": "加入第一个 b", "state": "l=0 / 窗口 ab / best=2", "reason": "继续扩大合法窗口。", "visual": {"kind": "array", "cells": ["a", "b", "b", "a"], "active": [0, 1], "markers": {"0": "L", "1": "R"}, "caption": "高亮表示当前关注的区间或状态；下方数字为下标。"}}, {"action": "加入第二个 b", "state": "l=2 / 窗口 b / best=2", "reason": "必须先移走 a，再移走旧 b；只移一次不够。", "visual": {"kind": "array", "cells": ["a", "b", "b", "a"], "active": [2], "markers": {"2": "L=R"}, "caption": "高亮表示当前关注的区间或状态；下方数字为下标。"}}, {"action": "加入最后一个 a", "state": "l=2 / 窗口 ba / best=2", "reason": "最优长度是 2；左端不能倒退。", "visual": {"kind": "array", "cells": ["a", "b", "b", "a"], "active": [2, 3], "markers": {"2": "L", "3": "R"}, "caption": "高亮表示当前关注的区间或状态；下方数字为下标。"}}], "codeNotes": ["count[c]++：只可能新增当前字符的冲突。", "while 而非 if：一次移动不保证合法。", "r-left+1：恢复合法后结算最长长度。"], "trap": "abba 中只执行一次收缩会留下 bb，产生非法窗口。", "quiz": {"question": "为什么两层循环仍是 O(n)？", "options": ["while 永远只执行一次", "字符不可能重复", "两个端点各自只向右移动至多 n 次"], "correct": 2, "why": "摊还计数统计的是整个运行过程的移动次数。"}, "practice": [{"id": "904", "title": "水果成篮", "url": "https://leetcode.cn/problems/fruit-into-baskets/", "hint": "合法条件改为窗口至多两种水果。"}, {"id": "1004", "title": "最大连续1的个数 III", "url": "https://leetcode.cn/problems/max-consecutive-ones-iii/", "hint": "合法条件改为窗口中的 0 不超过 k。"}], "source": "https://leetcode.cn/discuss/post/0viNMK/", "code": "// 不定长窗口 · 最长不重复\n// 使用前提：按字节统计；UTF-8 汉字需先解码为字符。\n// 状态 / 不变量：每次更新 best 前，窗口内每种字符最多出现一次。\n// 复杂度：O(n) 时间 / O(1) 空间\n\nint longestUnique(const string& s) {\n    vector<int> count(256);\n    int left=0, best=0;\n    for (int r=0; r<(int)s.size(); ++r) {\n        // 按无符号字节索引，避免负char下标。\n        unsigned char c=s[r]; ++count[c];\n        // 重复可能不在左端，必须一直缩到合法。\n        while (count[c]>1) --count[(unsigned char)s[left++]];\n        // 此时窗口合法，才可以更新最长长度。\n        best=max(best,r-left+1);\n    }\n    return best;\n}", "contract": "按字节统计；UTF-8 汉字需先解码为字符。", "cost": "O(n) 时间 / O(1) 空间"}, {"group": 1, "template": 0, "id": "1-0", "title": "左闭右开 lower_bound", "problem": "在排序数组中查找元素的第一个和最后一个位置", "problemId": "34", "url": "https://leetcode.cn/problems/find-first-and-last-position-of-element-in-sorted-array/", "signal": "排序数组中找第一个满足 ≥ target 的位置，再组合出区间。", "naive": "逐个扫描是 O(n)，有序性允许一次排除一半。", "invariant": "[0,l) 都小于 target；[r,n) 都大于等于 target，待确定区间为 [l,r)。", "frames": [{"action": "a=[1,3,3,7]，找 3", "state": "l=0 / r=4 / mid=2", "reason": "a[2]=3，答案可能就是 2，因此保留它。", "visual": {"kind": "array", "cells": ["1", "3", "3", "7"], "active": [0, 1, 2, 3], "markers": {"2": "mid"}, "caption": "高亮表示当前关注的区间或状态；下方数字为下标。"}}, {"action": "收缩右边界", "state": "l=0 / r=2 / mid=1", "reason": "a[1]=3，再令 r=1。", "visual": {"kind": "array", "cells": ["1", "3", "3", "7"], "active": [0, 1], "markers": {"1": "mid"}, "caption": "高亮表示当前关注的区间或状态；下方数字为下标。"}}, {"action": "检查左半边", "state": "l=0 / r=1 / mid=0", "reason": "a[0]=1，令 l=1。", "visual": {"kind": "array", "cells": ["1", "3", "3", "7"], "active": [0], "markers": {"0": "mid"}, "caption": "高亮表示当前关注的区间或状态；下方数字为下标。"}}, {"action": "左右相遇", "state": "l=r=1，返回 1", "reason": "首次出现是 1；首个 >3 的位置为 3，所以末次出现是 2。", "visual": {"kind": "array", "cells": ["1", "3", "3", "7"], "active": [1], "markers": {"1": "答案"}, "caption": "高亮表示当前关注的区间或状态；下方数字为下标。"}}], "codeNotes": ["r=a.size()：允许答案为 n，表示不存在。", "a[mid]<target 时 l=mid+1，mid 已被排除。", "否则 r=mid，mid 仍可能是答案。"], "trap": "lower_bound 返回 n 时不能访问 a[n]。找末次位置可另写首个 >target，避免 target+1 溢出。", "quiz": {"question": "空数组的 lower_bound 应返回什么？", "options": ["-1", "发生越界", "0"], "correct": 2, "why": "区间初始为空，循环不执行，返回插入位置 0。"}, "practice": [{"id": "35", "title": "搜索插入位置", "url": "https://leetcode.cn/problems/search-insert-position/", "hint": "直接返回插入位置。"}, {"id": "744", "title": "寻找比目标字母大的最小字母", "url": "https://leetcode.cn/problems/find-smallest-letter-greater-than-target/", "hint": "把判断改为严格大于，最后处理循环回到首字符。"}], "source": "https://leetcode.cn/discuss/post/SqopEo/", "code": "// 左闭右开 lower_bound\n// 使用前提：a 已按非降序排序；返回第一个 ≥ target 的下标。\n// 状态 / 不变量：[0,l) 都小于 target；[r,n) 都大于等于 target，待确定区间为 [l,r)。\n// 复杂度：O(log n) 时间 / O(1) 空间\n\nint lowerBound(const vector<int>& a, int target) {\n    // 搜索区间[l,r)，允许返回n表示不存在。\n    int l=0, r=(int)a.size();\n    while (l<r) {\n        int mid=l+(r-l)/2;\n        // 小于目标可排除mid；否则mid仍可能是答案。\n        if (a[mid]<target) l=mid+1;\n        else r=mid;\n    }\n    // 循环结束l==r，正是首个不小于target的位置。\n    return l;\n}", "contract": "a 已按非降序排序；返回第一个 ≥ target 的下标。", "cost": "O(log n) 时间 / O(1) 空间"}, {"group": 1, "template": 1, "id": "1-1", "title": "二分答案 · 最小可行速度", "problem": "爱吃香蕉的珂珂", "problemId": "875", "url": "https://leetcode.cn/problems/koko-eating-bananas/", "signal": "求最小可行参数，且可行性存在单调分界。", "naive": "从 1 到最大堆逐一试速度太慢；每次判定能排除半段速度。", "invariant": "速度越大，总耗时不会变多；答案始终在闭区间 [l,r] 内。", "frames": [{"action": "piles=[3,6,7,11]，h=8", "state": "搜索 [1,11] / mid=6 / 耗时=6", "reason": "速度 6 可行，但可能还能更慢，r=6。"}, {"action": "搜索 [1,6]", "state": "mid=3 / 耗时=10", "reason": "超时，速度 1..3 都不可行，l=4。"}, {"action": "搜索 [4,6]", "state": "mid=5 / 耗时=8", "reason": "可行，r=5。"}, {"action": "搜索 [4,5]", "state": "mid=4 / 耗时=8 / 答案=4", "reason": "可行，r=4；边界相遇。"}], "codeNotes": ["上界 max(piles)：每堆最多一小时；要求 h≥堆数。", "(x+mid-1)/mid：整数向上取整，使用 long long 防溢出。", "可行时收右端，不要立即返回 mid。"], "trap": "二分前必须证明单调性。若题目要求耗时恰好 h，谓词通常不能直接写成 hours==h。", "quiz": {"question": "最小可行值的判定成功后该怎么做？", "options": ["把左边界移到 mid+1", "保留 mid，继续向左找", "直接返回 mid"], "correct": 1, "why": "成功只能说明 mid 是可行解，不能说明它最小。"}, "practice": [{"id": "1011", "title": "在 D 天内送达包裹的能力", "url": "https://leetcode.cn/problems/capacity-to-ship-packages-within-d-days/", "hint": "候选参数换成船的容量，顺序装货模拟天数。"}, {"id": "410", "title": "分割数组的最大值", "url": "https://leetcode.cn/problems/split-array-largest-sum/", "hint": "非负数组下，用分组数≤k 判断最大段和是否可行。"}], "source": "https://leetcode.cn/discuss/post/SqopEo/", "code": "// 二分答案 · 最小可行速度\n// 使用前提：piles 非空且均为正数；h ≥ piles.size()。\n// 状态 / 不变量：速度越大，总耗时不会变多；答案始终在闭区间 [l,r] 内。\n// 复杂度：O(n log M) 时间 / O(1) 空间\n\nint minSpeed(const vector<int>& piles, long long h) {\n    // 最慢速度1；最大堆大小保证每堆最多耗时1小时。\n    int l=1, r=*max_element(piles.begin(),piles.end());\n    while (l<r) {\n        int mid=l+(r-l)/2;\n        // 每堆独立向上取整，累加使用long long。\n        long long hours=0;\n        for (int x:piles) hours+=(x+0LL+mid-1)/mid;\n        // 可行则保留mid并向更小速度搜索。\n        if (hours<=h) r=mid;\n        else l=mid+1;\n    }\n    return l;\n}", "contract": "piles 非空且均为正数；h ≥ piles.size()。", "cost": "O(n log M) 时间 / O(1) 空间"}, {"group": 2, "template": 0, "id": "2-0", "title": "下一个严格更大 · 等待天数", "problem": "每日温度", "problemId": "739", "url": "https://leetcode.cn/problems/daily-temperatures/", "signal": "每个位置找右侧第一个严格更大元素。", "naive": "每一天向右扫描，最坏 O(n²)。让还未找到答案的位置等待新元素统一结算。", "invariant": "栈存下标，对应温度从底到顶不增；弹出时第一次遇到更暖日。", "frames": [{"action": "温度 [73,71,74,74]", "state": "i=0 / 栈=[0:73]", "reason": "尚无更暖日，入栈等待。"}, {"action": "读入 71", "state": "i=1 / 栈=[0:73,1:71]", "reason": "比栈顶低，不能解决旧位置。"}, {"action": "读入第一个 74", "state": "弹出 1、0 / ans=[2,1,0,0]", "reason": "先解决 71，再解决 73，距离用当前下标减旧下标。"}, {"action": "读入第二个 74", "state": "栈=[2:74,3:74]", "reason": "相等不是更暖，不弹出；未解决的答案为 0。"}], "codeNotes": ["栈里放下标：计算距离需要位置。", "while 当前温度>栈顶温度：一次可解决多个旧位置。", "弹出后赋值 i-j：右侧首个更大元素已确定。"], "trap": "把 > 写成 ≥ 会把相同温度错误地当成更暖日。", "quiz": {"question": "数组严格递减时，时间复杂度是多少？", "options": ["O(log n)", "O(n)，每个位置只入栈一次", "O(n²)，栈会越来越长"], "correct": 1, "why": "栈长影响空间，不会导致重复扫描。"}, "practice": [{"id": "496", "title": "下一个更大元素 I", "url": "https://leetcode.cn/problems/next-greater-element-i/", "hint": "记录下一个更大值而非距离。"}, {"id": "503", "title": "下一个更大元素 II", "url": "https://leetcode.cn/problems/next-greater-element-ii/", "hint": "循环扫描两轮，但只为原下标记录答案。"}], "source": "https://leetcode.cn/discuss/post/9oZFK9/", "code": "// 下一个严格更大 · 等待天数\n// 使用前提：相等温度不能结算。\n// 状态 / 不变量：栈存下标，对应温度从底到顶不增；弹出时第一次遇到更暖日。\n// 复杂度：O(n) 时间 / O(n) 空间\n\nvector<int> nextWarmer(const vector<int>& a) {\n    // 栈存还没找到更暖日的下标；默认答案为0。\n    vector<int> st, ans(a.size());\n    for (int i=0;i<(int)a.size();++i) {\n        // 严格更暖才结算，相等温度继续等待。\n        while (!st.empty() && a[st.back()]<a[i]) {\n            // 下标差就是等待天数，每个旧下标只结算一次。\n            int j=st.back(); st.pop_back(); ans[j]=i-j;\n        }\n        st.push_back(i);\n    }\n    return ans;\n}", "contract": "相等温度不能结算。", "cost": "O(n) 时间 / O(n) 空间"}, {"group": 2, "template": 1, "id": "2-1", "title": "柱状图最大矩形", "problem": "柱状图中最大的矩形", "problemId": "84", "url": "https://leetcode.cn/problems/largest-rectangle-in-histogram/", "signal": "柱状图最大面积：固定最低高度，寻找能延伸的左右边界。", "naive": "枚举所有区间再找最低柱很慢；每根柱只需在遇到更矮柱时结算。", "invariant": "单调栈保留尚未确定右边界的柱；弹栈后新栈顶给出左侧阻挡边界。", "frames": [{"action": "高度 [2,1,5,6,2,3]", "state": "读到 i=1，高度1 / 弹出高度2", "reason": "右边界1，左边界-1，面积2×1=2。"}, {"action": "读完下标3", "state": "栈内下标 [1,2,3] / 高度[1,5,6]", "reason": "高度递增，右边界暂时未知。"}, {"action": "i=4，高度2", "state": "弹6：面积6×1；弹5：面积5×2=10", "reason": "5 的有效下标区间是[2,3]。"}, {"action": "末尾哨兵结算", "state": "当前最优面积=10", "reason": "额外的高度0把剩余候选结算完。"}], "codeNotes": ["弹出高度 h 后再看栈顶，得到左边界 left。", "宽度 i-left-1，不包括两侧阻挡柱。", "末尾补一个 0，统一处理未结算的位置。"], "trap": "不能把宽度写成 i-left。重复高度的弹栈规则必须与边界解释一致。", "quiz": {"question": "栈顶弹出后为空，左边界用什么？", "options": ["-1", "0", "当前下标"], "correct": 0, "why": "没有左侧阻挡，矩形可延伸到下标 0。"}, "practice": [{"id": "85", "title": "最大矩形", "url": "https://leetcode.cn/problems/maximal-rectangle/", "hint": "每一行累计连续1的高度，再调用柱状图模板。"}, {"id": "907", "title": "子数组的最小值之和", "url": "https://leetcode.cn/problems/sum-of-subarray-minimums/", "hint": "改成计算每个元素作为最小值的贡献，重复值需一边严格一边非严格。"}], "source": "https://leetcode.cn/discuss/post/9oZFK9/", "code": "// 柱状图最大矩形\n// 使用前提：高度非负；用 long long 返回面积。\n// 状态 / 不变量：单调栈保留尚未确定右边界的柱；弹栈后新栈顶给出左侧阻挡边界。\n// 复杂度：O(n) 时间 / O(n) 空间\n\nlong long largestRectangle(vector<int> h) {\n    // 末尾0作为哨兵，触发剩余正高度柱的结算。\n    h.push_back(0);\n    vector<int> st;\n    long long best=0;\n    for (int i=0;i<(int)h.size();++i) {\n        while (!st.empty() && h[st.back()]>h[i]) {\n            int height=h[st.back()]; st.pop_back();\n            // 弹栈之后的新栈顶是左侧边界；没有则为-1。\n            int left=st.empty()?-1:st.back();\n            // 两侧边界不计入宽度，先转long long再乘。\n            best=max(best,1LL*height*(i-left-1));\n        }\n        st.push_back(i);\n    }\n    return best;\n}", "contract": "高度非负；用 long long 返回面积。", "cost": "O(n) 时间 / O(n) 空间"}, {"group": 3, "template": 0, "id": "3-0", "title": "迭代 DFS · 岛屿数", "problem": "岛屿数量", "problemId": "200", "url": "https://leetcode.cn/problems/number-of-islands/", "signal": "网格按四方向连通，要求连通块数或每块面积。", "naive": "每次遇到陆地都加一会重复数同一座岛；先把整个连通块标记完。", "invariant": "每个未访问陆地启动一次遍历，遍历结束后该岛全部被标记。", "frames": [{"action": "网格 110 / 010 / 001", "state": "从(0,0)发现新岛 / count=1", "reason": "将起点标为已访问，再入栈。", "visual": {"kind": "grid", "cells": ["1", "1", "0", "0", "1", "0", "0", "0", "1"], "active": [0], "markers": {}, "caption": "行列均从0开始。高亮为已访问陆地。"}}, {"action": "遍历第一块", "state": "访问 (0,1)、(1,1)", "reason": "四方向可达，属于同一座岛。", "visual": {"kind": "grid", "cells": ["1", "1", "0", "0", "1", "0", "0", "0", "1"], "active": [0, 1, 4], "markers": {}, "caption": "行列均从0开始。高亮为已访问陆地。"}}, {"action": "扫描到(2,2)", "state": "count=2", "reason": "与(1,1)只有对角接触，不算连通。", "visual": {"kind": "grid", "cells": ["1", "1", "0", "0", "1", "0", "0", "0", "1"], "active": [0, 1, 4, 8], "markers": {}, "caption": "行列均从0开始。高亮为已访问陆地。"}}, {"action": "扫描结束", "state": "返回2", "reason": "每个格子最多访问一次。", "visual": {"kind": "grid", "cells": ["1", "1", "0", "0", "1", "0", "0", "0", "1"], "active": [0, 1, 4, 8], "markers": {}, "caption": "行列均从0开始。高亮为已访问陆地。"}}], "codeNotes": ["访问标记在入栈时设置，避免重复入栈。", "四个方向都检查边界，再访问格子。", "迭代栈避免大网格递归过深。"], "trap": "如果题目允许八方向，连通定义就变了；若还需要原网格，应另开 visited。", "quiz": {"question": "示例右下角为什么不属于第一座岛？", "options": ["四方向不包含对角线", "它距离起点最远", "只能向右向下移动"], "correct": 0, "why": "先读清楚“相邻”的定义，再选方向数组。"}, "practice": [{"id": "695", "title": "岛屿的最大面积", "url": "https://leetcode.cn/problems/max-area-of-island/", "hint": "每次遍历累计面积，取最大值。"}, {"id": "130", "title": "被围绕的区域", "url": "https://leetcode.cn/problems/surrounded-regions/", "hint": "从边界上的 O 反向标记安全区域。"}], "source": "https://leetcode.cn/discuss/post/YiXPXW/", "code": "// 迭代 DFS · 岛屿数\n// 使用前提：矩形字符网格，只含 0/1；会原地修改网格。\n// 状态 / 不变量：每个未访问陆地启动一次遍历，遍历结束后该岛全部被标记。\n// 复杂度：O(mn) 时间 / O(mn) 额外空间\n\nint countIslands(vector<string>& a) {\n    if(a.empty()||a[0].empty()) return 0;\n    int m=a.size(),n=a[0].size(),ans=0;\n    int d[5]={1,0,-1,0,1};\n    for(int i=0;i<m;++i) for(int j=0;j<n;++j) {\n        // 跳过海水和已访问陆地。\n        if(a[i][j]!='1') continue;\n        // 发现新连通块；起点立即标记，避免重复加入。\n        ++ans; vector<pair<int,int>> st{{i,j}}; a[i][j]='0';\n        while(!st.empty()) {\n            auto cell=st.back();st.pop_back();\n            for(int k=0;k<4;++k) {\n                int x=cell.first+d[k],y=cell.second+d[k+1];\n                if(x>=0&&x<m&&y>=0&&y<n&&a[x][y]=='1') {\n                    // 邻居入栈时就标记，保证每格最多加入一次。\n                    a[x][y]='0';st.push_back({x,y});\n                }\n            }\n        }\n    }\n    return ans;\n}", "contract": "矩形字符网格，只含 0/1；会原地修改网格。", "cost": "O(mn) 时间 / O(mn) 额外空间"}, {"group": 3, "template": 1, "id": "3-1", "title": "多源 BFS · 最近 0 的距离", "problem": "01 矩阵", "problemId": "542", "url": "https://leetcode.cn/problems/01-matrix/", "signal": "多个起点向外扩散，求每格到最近起点的无权距离。", "naive": "从每个 1 单独 BFS 重复太多；从所有 0 同时出发共用搜索。", "invariant": "队列按距离非递减出队，格子第一次被发现时已获得最短距离。", "frames": [{"action": "矩阵 000 / 010 / 111", "state": "全部0入队，距离为0", "reason": "多源相当于同时启动多个同速波前。", "visual": {"kind": "grid", "cells": ["0", "0", "0", "0", "∞", "0", "∞", "∞", "∞"], "active": [0, 1, 2, 3, 5], "markers": {}, "caption": "行列均从0开始。数字为到最近0的距离；∞表示尚未发现。"}}, {"action": "处理距离0层", "state": "(1,1)、(2,0)、(2,2) 距离=1", "reason": "首次发现就赋距离并入队。", "visual": {"kind": "grid", "cells": ["0", "0", "0", "0", "1", "0", "1", "∞", "1"], "active": [4, 6, 8], "markers": {}, "caption": "行列均从0开始。数字为到最近0的距离；∞表示尚未发现。"}}, {"action": "处理距离1层", "state": "(2,1) 距离=2", "reason": "从任何距离1的邻居都只需再走一步。", "visual": {"kind": "grid", "cells": ["0", "0", "0", "0", "1", "0", "1", "2", "1"], "active": [7], "markers": {}, "caption": "行列均从0开始。数字为到最近0的距离；∞表示尚未发现。"}}, {"action": "队列清空", "state": "结果 000 / 010 / 121", "reason": "每格只入队一次，时间 O(mn)。", "visual": {"kind": "grid", "cells": ["0", "0", "0", "0", "1", "0", "1", "2", "1"], "active": [0, 1, 2, 3, 4, 5, 6, 7, 8], "markers": {}, "caption": "行列均从0开始。数字为到最近0的距离；∞表示尚未发现。"}}], "codeNotes": ["起点先全部入队，不要逐个清空队列。", "未访问距离设为 -1，兼做 visited。", "邻居距离=当前距离+1，仅在边权一致时成立。"], "trap": "边权不同不能直接套普通 BFS；距离最小不等于经过边数最少。", "quiz": {"question": "首次到达就确定距离，依赖哪个前提？", "options": ["起点只有一个", "网格没有障碍", "每次移动的代价相同"], "correct": 2, "why": "BFS 按边数分层，等权才对应最短代价。"}, "practice": [{"id": "994", "title": "腐烂的橘子", "url": "https://leetcode.cn/problems/rotting-oranges/", "hint": "所有腐烂橘子同时入队，最后检查是否还有新鲜橘子。"}, {"id": "1162", "title": "地图分析", "url": "https://leetcode.cn/problems/as-far-from-land-as-possible/", "hint": "从所有陆地出发，取海洋距离的最大值。"}], "source": "https://leetcode.cn/discuss/post/YiXPXW/", "code": "// 多源 BFS · 最近 0 的距离\n// 使用前提：矩形网格；若没有源点，距离保持 −1。\n// 状态 / 不变量：队列按距离非递减出队，格子第一次被发现时已获得最短距离。\n// 复杂度：O(mn) 时间 / O(mn) 空间\n\nvector<vector<int>> nearestZero(const vector<vector<int>>& a) {\n    if(a.empty()||a[0].empty()) return {};\n    int m=a.size(),n=a[0].size(),d[5]={1,0,-1,0,1};\n    // -1同时表示尚未访问；0是实际源点距离。\n    vector<vector<int>> dist(m,vector<int>(n,-1));\n    queue<pair<int,int>> q;\n    for(int i=0;i<m;++i) for(int j=0;j<n;++j)\n        // 所有0同时入队，构成多源BFS的第0层。\n        if(a[i][j]==0) {dist[i][j]=0;q.push({i,j});}\n    while(!q.empty()) {\n        auto cell=q.front();q.pop();\n        for(int k=0;k<4;++k) {\n            int x=cell.first+d[k],y=cell.second+d[k+1];\n            if(x>=0&&x<m&&y>=0&&y<n&&dist[x][y]<0) {\n                // 第一次发现即获得最短距离：父距离加1。\n                dist[x][y]=dist[cell.first][cell.second]+1;\n                q.push({x,y});\n            }\n        }\n    }\n    return dist;\n}", "contract": "矩形网格；若没有源点，距离保持 −1。", "cost": "O(mn) 时间 / O(mn) 空间"}, {"group": 4, "template": 0, "id": "4-0", "title": "异或抵消", "problem": "只出现一次的数字", "problemId": "136", "url": "https://leetcode.cn/problems/single-number/", "signal": "除一个数外，其余每个数都恰好出现两次。", "naive": "哈希频次需要额外空间；异或具有交换结合律，同值两次抵消。", "invariant": "处理前缀的异或，等于该前缀中出现奇数次的数的异或。", "frames": [{"action": "输入 [4,1,2,1,2]", "state": "result=0", "reason": "0 是异或单位元。"}, {"action": "依次读4、1、2", "state": "result=4→5→7", "reason": "中间值不必是输入中的某个值。"}, {"action": "再读1", "state": "result=6", "reason": "两个1的贡献已经抵消。"}, {"action": "再读2", "state": "result=4", "reason": "两个2也抵消，只剩4。"}], "codeNotes": ["result ^= x：位上的模2加法，不进位。", "循环顺序不影响结果。", "空间 O(1)，不用排序也不改变输入。"], "trap": "出现三次的数字不会抵消；两个单独出现的数异或后也不能直接分离。", "quiz": {"question": "如果有两个只出现一次的数 a,b，直接异或得到什么？", "options": ["较小的一个", "a+b", "a XOR b"], "correct": 2, "why": "需再按 a XOR b 的某个置位分组求解。"}, "practice": [{"id": "260", "title": "只出现一次的数字 III", "url": "https://leetcode.cn/problems/single-number-iii/", "hint": "按异或结果的一个置位把两种单数分开。"}, {"id": "137", "title": "只出现一次的数字 II", "url": "https://leetcode.cn/problems/single-number-ii/", "hint": "每一位统计次数模3，不能沿用成对抵消。"}], "source": "https://leetcode.cn/discuss/post/dHn9Vk/", "code": "// 异或抵消\n// 使用前提：除一个元素出现一次外，其余元素都恰好出现两次。\n// 状态 / 不变量：处理前缀的异或，等于该前缀中出现奇数次的数的异或。\n// 复杂度：O(n) 时间 / O(1) 空间\n\nint singleNumber(const vector<int>& a) {\n    // 0是异或的单位元。\n    int result=0;\n    // 同值成对抵消；顺序不影响结果。\n    for(int x:a) result^=x;\n    // 前提成立时，剩下的就是唯一出现一次的数。\n    return result;\n}", "contract": "除一个元素出现一次外，其余元素都恰好出现两次。", "cost": "O(n) 时间 / O(1) 空间"}, {"group": 4, "template": 1, "id": "4-1", "title": "枚举子集（含空集）", "problem": "子集", "problemId": "78", "url": "https://leetcode.cn/problems/subsets/", "signal": "集合规模小，用二进制位表示是否选取，枚举某集合的全部子集。", "naive": "枚举所有 2^n 个掩码再过滤会浪费；(s-1)&mask 只走合法子集。", "invariant": "s 的每个置位都来自 mask；每一步严格递减，直到空集。", "frames": [{"action": "集合位 mask=101₂", "state": "s=101₂，对应选第0和第2项", "reason": "从全集开始。", "visual": {"kind": "array", "cells": ["1", "0", "1"], "active": [0, 1, 2], "markers": {}, "caption": "从左到右为第2、1、0位，1表示选择对应元素。"}}, {"action": "计算 (s-1)&mask", "state": "100₂", "reason": "先减1，再清掉不在 mask 的位。", "visual": {"kind": "array", "cells": ["1", "0", "0"], "active": [0, 1, 2], "markers": {}, "caption": "从左到右为第2、1、0位，1表示选择对应元素。"}}, {"action": "继续枚举", "state": "001₂", "reason": "跳过包含非法第1位的掩码。", "visual": {"kind": "array", "cells": ["0", "0", "1"], "active": [0, 1, 2], "markers": {}, "caption": "从左到右为第2、1、0位，1表示选择对应元素。"}}, {"action": "到达空集", "state": "000₂，输出后停止", "reason": "再递推会回到 mask，因此必须 break。", "visual": {"kind": "array", "cells": ["0", "0", "0"], "active": [0, 1, 2], "markers": {}, "caption": "从左到右为第2、1、0位，1表示选择对应元素。"}}], "codeNotes": ["使用 unsigned 明确位运算语义。", "先输出当前 s，再判断 s==0。", "2^popcount(mask) 个结果，输出本身就有这个量级。"], "trap": "这一模板枚举“给定集合的子集”，不是枚举连续子数组。", "quiz": {"question": "mask=0 时有多少个子集？", "options": ["无限多个", "1 个：空集", "0 个"], "correct": 1, "why": "空集也是子集，停止条件不能跳过它。"}, "practice": [{"id": "78", "title": "子集", "url": "https://leetcode.cn/problems/subsets/", "hint": "把每个置位映射回数组元素。"}, {"id": "90", "title": "子集 II", "url": "https://leetcode.cn/problems/subsets-ii/", "hint": "相同元素会让不同掩码对应同一结果，需要去重策略。"}], "source": "https://leetcode.cn/discuss/post/dHn9Vk/", "code": "// 枚举子集（含空集）\n// 使用前提：mask 为无符号位集合；输出规模为 2^置位数。\n// 状态 / 不变量：s 的每个置位都来自 mask；每一步严格递减，直到空集。\n// 复杂度：O(2^popcount(mask)) 时间与输出空间\n\nvector<unsigned> submasks(unsigned mask) {\n    vector<unsigned> out;\n    // 先从全集开始，逐步枚举更小的合法子掩码。\n    unsigned s=mask;\n    while(true) {\n        // 先收集当前集合，包含最后的空集。\n        out.push_back(s);\n        // 空集输出后必须停，否则下一步会回到mask。\n        if(s==0) break;\n        s=(s-1)&mask;\n    }\n    return out;\n}", "contract": "mask 为无符号位集合；输出规模为 2^置位数。", "cost": "O(2^popcount(mask)) 时间与输出空间"}, {"group": 5, "template": 0, "id": "5-0", "title": "Kahn 拓扑排序", "problem": "课程表", "problemId": "207", "url": "https://leetcode.cn/problems/course-schedule/", "signal": "有向依赖关系，判断能否按先后顺序完成全部任务。", "naive": "反复扫描未完成课程较慢；入度记录还剩多少前置条件。", "invariant": "入度0的节点没有未处理前驱，可以安全加入结果。", "frames": [{"action": "边 0→1、0→2、1→3、2→3", "state": "入度 [0,1,1,2] / 队列[0]", "reason": "箭头从先修课程指向后续课程。"}, {"action": "处理0", "state": "入度 [0,0,0,2] / 队列[1,2]", "reason": "1和2都已满足前置条件。"}, {"action": "处理1，再处理2", "state": "3的入度 2→1→0 / 队列[3]", "reason": "只在降到0时入队。"}, {"action": "处理3", "state": "输出4个节点，可完成", "reason": "若输出少于 n，剩余部分包含依赖环。"}], "codeNotes": ["先计算所有边的终点入度。", "每输出一个节点，删除它的出边。", "模板返回顺序；判断无环须检查 order.size()==n。"], "trap": "有多个合法拓扑序，不必与某个样例顺序逐项相同。", "quiz": {"question": "如果两个课程互为先修，初始队列怎样？", "options": ["两个同时入队", "这两个节点都不能入队", "任意选一个即可"], "correct": 1, "why": "入度都不为0，无法完成；不应强行打破依赖。"}, "practice": [{"id": "210", "title": "课程表 II", "url": "https://leetcode.cn/problems/course-schedule-ii/", "hint": "直接返回拓扑顺序，若数量不足则返回空。"}, {"id": "1462", "title": "课程表 IV", "url": "https://leetcode.cn/problems/course-schedule-iv/", "hint": "在拓扑过程中传播祖先集合，回答先修查询。"}], "source": "https://leetcode.cn/discuss/post/01LUak/", "code": "// Kahn 拓扑排序\n// 使用前提：g 是编号 0..n−1 的有向邻接表。返回不足 n 个节点说明有环。\n// 状态 / 不变量：入度0的节点没有未处理前驱，可以安全加入结果。\n// 复杂度：O(V+E) 时间 / O(V) 辅助空间\n\nvector<int> topoSort(const vector<vector<int>>& g) {\n    int n=g.size();vector<int> degree(n),order;queue<int> q;\n    // 边x→y表示先x后y，增加终点的入度。\n    for(auto& es:g) for(int y:es) ++degree[y];\n    // 没有未处理前驱的节点可以开始。\n    for(int x=0;x<n;++x) if(degree[x]==0) q.push(x);\n    while(!q.empty()) {\n        int x=q.front();q.pop();order.push_back(x);\n        // 删除当前节点的出边；入度恰好变0时入队。\n        for(int y:g[x]) if(--degree[y]==0) q.push(y);\n    }\n    return order;\n}", "contract": "g 是编号 0..n−1 的有向邻接表。返回不足 n 个节点说明有环。", "cost": "O(V+E) 时间 / O(V) 辅助空间"}, {"group": 5, "template": 1, "id": "5-1", "title": "Dijkstra · 非负权最短路", "problem": "网络延迟时间", "problemId": "743", "url": "https://leetcode.cn/problems/network-delay-time/", "signal": "有向图非负权，从单源出发求到所有点的最短代价。", "naive": "DFS 遍历顺序不代表距离；堆每次选当前最短的未结算候选。", "invariant": "非负边保证当前最小距离的有效堆项出队后，不会被更长前缀改进。", "frames": [{"action": "边 0→1:1，0→2:4，1→2:2", "state": "dist=[0,∞,∞] / 堆[(0,0)]", "reason": "只给起点距离0。"}, {"action": "出队0并松弛", "state": "dist=[0,1,4]", "reason": "把到1、2的新候选压堆。"}, {"action": "出队1并松弛", "state": "dist=[0,1,3]", "reason": "1+2比4短，再压入(3,2)。"}, {"action": "处理2，再遇旧(4,2)", "state": "跳过4，因为 dist[2]=3", "reason": "失效堆项不再次扩展；网络延迟为 max(dist)=3。"}], "codeNotes": ["greater<P> 创建小根堆。", "dx!=dist[x] 跳过旧候选。", "只有距离严格变小才压堆，防止零权环重复。"], "trap": "普通 Dijkstra 的正确性证明需要非负边。未到达点仍为 INF，网络延迟题应返回 -1。", "quiz": {"question": "堆中同一个节点出现两次意味着什么？", "options": ["可能是旧距离与改进后的新距离", "一定有负环", "实现一定有错"], "correct": 0, "why": "懒删除允许多次入堆，通过距离检查排除失效项。"}, "practice": [{"id": "1631", "title": "最小体力消耗路径", "url": "https://leetcode.cn/problems/path-with-minimum-effort/", "hint": "路径代价改成边权最大值，松弛用 max 而非相加。"}, {"id": "1976", "title": "到达目的地的方案数", "url": "https://leetcode.cn/problems/number-of-ways-to-arrive-at-destination/", "hint": "同时维护达到最短距离的方案数，并处理同距离松弛。"}], "source": "https://leetcode.cn/discuss/post/01LUak/", "code": "// Dijkstra · 非负权最短路\n// 使用前提：g[x] 存 {目标,权重}，权重非负；最短路径和须小于 INF。\n// 状态 / 不变量：非负边保证当前最小距离的有效堆项出队后，不会被更长前缀改进。\n// 复杂度：O((V+E)log(V+E)) 时间 / O(V+E) 空间\n\nvector<long long> dijkstra(const vector<vector<pair<int,int>>>& g,int s) {\n    const long long INF=1LL<<62;\n    vector<long long> dist(g.size(),INF);dist[s]=0;\n    using P=pair<long long,int>;\n    // greater创建小根堆，优先扩展最小距离候选。\n    priority_queue<P,vector<P>,greater<P>> pq;pq.push({0,s});\n    while(!pq.empty()) {\n        auto cur=pq.top();pq.pop();\n        long long dx=cur.first;int x=cur.second;\n        // 堆中可能残留旧距离，直接跳过失效项。\n        if(dx!=dist[x]) continue;\n        for(auto edge:g[x]) {\n            int y=edge.first,w=edge.second;\n            // 严格改善时才松弛入堆，避免零权环重复扩展。\n            if(dx+w<dist[y]) {dist[y]=dx+w;pq.push({dist[y],y});}\n        }\n    }\n    return dist;\n}", "contract": "g[x] 存 {目标,权重}，权重非负；最短路径和须小于 INF。", "cost": "O((V+E)log(V+E)) 时间 / O(V+E) 空间"}, {"group": 5, "template": 2, "id": "5-2", "title": "限制边数的最短路", "problem": "K 站中转内最便宜的航班", "problemId": "787", "url": "https://leetcode.cn/problems/cheapest-flights-within-k-stops/", "signal": "最短代价之外还有最多边数限制，状态要包含使用边数。", "naive": "只按城市保留最便宜价格，会丢掉更贵但剩余转机次数更多的路径。", "invariant": "第 step 轮后，dist[v] 表示使用至多 step 条边的最小代价。", "frames": [{"action": "边 0→1:100，1→2:100，0→2:500", "state": "初始 dist=[0,∞,∞]", "reason": "还没用任何边。"}, {"action": "第一轮", "state": "next=[0,100,500]", "reason": "只从旧 dist 松弛，所以不能本轮连走两条边。"}, {"action": "第二轮", "state": "next=[0,100,200]", "reason": "允许经过1再到2。"}, {"action": "最多一次中转", "state": "最多2条边，答案200", "reason": "中转点数 k 与边数 k+1 区分开。"}], "codeNotes": ["auto next=dist：允许少于限制的边数。", "读取旧 dist，写入 next，防止串联松弛。", "limit 是边数，具体题目要先换算。"], "trap": "在同一个 dist 上原地更新，可能一轮用完任意多条边，破坏限制。", "quiz": {"question": "最多0次中转对应几条边？", "options": ["0条", "最多2条", "最多1条"], "correct": 2, "why": "起点直达终点有一条边，没有中转点。"}, "practice": [{"id": "787", "title": "K 站中转内最便宜的航班", "url": "https://leetcode.cn/problems/cheapest-flights-within-k-stops/", "hint": "先把 k 次中转换成 k+1 条边。"}, {"id": "743", "title": "网络延迟时间", "url": "https://leetcode.cn/problems/network-delay-time/", "hint": "去掉边数限制且非负权时，可换成 Dijkstra。"}], "source": "https://leetcode.cn/discuss/post/01LUak/", "code": "// 限制边数的最短路\n// 使用前提：edges 为 {起点,终点,权重}；最多 limit 条边，不是中转站数。\n// 状态 / 不变量：第 step 轮后，dist[v] 表示使用至多 step 条边的最小代价。\n// 复杂度：O(limit·(V+E)) 时间 / O(V) 空间\n\nvector<long long> limitedPath(int n,const vector<array<int,3>>& edges,int s,int limit) {\n    const long long INF=1LL<<62;\n    vector<long long> dist(n,INF);dist[s]=0;\n    // 每轮只增加一条允许使用的边；limit不是中转次数。\n    for(int step=0;step<limit;++step) {\n        // 从上一轮拷贝，允许答案使用少于step+1条边。\n        auto next=dist;\n        for(auto e:edges) if(dist[e[0]]!=INF)\n            // 读取旧dist、写入next，禁止同轮连续走多条边。\n            next[e[1]]=min(next[e[1]],dist[e[0]]+e[2]);\n        dist.swap(next);\n    }\n    return dist;\n}", "contract": "edges 为 {起点,终点,权重}；最多 limit 条边，不是中转站数。", "cost": "O(limit·(V+E)) 时间 / O(V) 空间"}, {"group": 6, "template": 0, "id": "6-0", "title": "线性 DP · 打家劫舍", "problem": "打家劫舍", "problemId": "198", "url": "https://leetcode.cn/problems/house-robber/", "signal": "线性序列选或不选，相邻选择冲突，求最大收益。", "naive": "枚举每间偷或不偷是指数级；相同前缀的最优解可复用。", "invariant": "f[i] 表示前 i 间的最大收益，只依赖 f[i-1] 与 f[i-2]。", "frames": [{"action": "金额 [2,7,9,3,1]", "state": "f[0]=0 / 前两步 2、7", "reason": "一间时选2；两间时较优为7。"}, {"action": "处理9", "state": "max(7,2+9)=11", "reason": "不选当前继承7；选当前就不能选7。"}, {"action": "处理3", "state": "max(11,7+3)=11", "reason": "局部金额并不直接决定取舍。"}, {"action": "处理1", "state": "max(11,11+1)=12", "reason": "最终选择2、9、1，总收益12。"}], "codeNotes": ["prev1 是上一前缀，prev2 是上上前缀。", "先用旧值计算 cur，再移动两个变量。", "空前缀为0，允许什么都不选。"], "trap": "不能每次贪心拿相邻两间较大的；选择会影响更远的组合。", "quiz": {"question": "环形房屋比线性房屋多了什么约束？", "options": ["第一间与最后一间不能同时选", "所有房屋只能选一间", "收益要除以2"], "correct": 0, "why": "分成不选首间、不选末间两种线性问题。"}, "practice": [{"id": "213", "title": "打家劫舍 II", "url": "https://leetcode.cn/problems/house-robber-ii/", "hint": "取区间[0,n-2]与[1,n-1]的较大值，单房间单独处理。"}, {"id": "740", "title": "删除并获得点数", "url": "https://leetcode.cn/problems/delete-and-earn/", "hint": "同数值收益先聚合，按值轴转成相邻冲突。"}], "source": "https://leetcode.cn/discuss/post/tXLS3i/", "code": "// 线性 DP · 打家劫舍\n// 使用前提：金额非负，允许不选任何房间。\n// 状态 / 不变量：f[i] 表示前 i 间的最大收益，只依赖 f[i-1] 与 f[i-2]。\n// 复杂度：O(n) 时间 / O(1) 空间\n\nlong long rob(const vector<int>& a) {\n    // prev1是上一前缀最优值，prev2是上上前缀最优值。\n    long long prev2=0,prev1=0;\n    for(int x:a) {\n        // 不选当前，或选当前并跳过上一间，二者取大。\n        long long cur=max(prev1,prev2+x);\n        // 计算完成后再滚动变量，不能提前覆盖旧值。\n        prev2=prev1;prev1=cur;\n    }\n    return prev1;\n}", "contract": "金额非负，允许不选任何房间。", "cost": "O(n) 时间 / O(1) 空间"}, {"group": 6, "template": 1, "id": "6-1", "title": "0/1 背包 · 恰好和可达", "problem": "分割等和子集", "problemId": "416", "url": "https://leetcode.cn/problems/partition-equal-subset-sum/", "signal": "每个元素最多一次，问能否恰好凑到目标和。", "naive": "枚举子集是 O(2^n)；当目标和可控，按容量保存可达性。", "invariant": "处理第 i 个元素后，f[j] 表示前 i 个元素能否恰好组成 j。", "frames": [{"action": "nums=[1,5,11,5]，总和22", "state": "目标11 / 可达{0}", "reason": "总和奇数时立即无解。"}, {"action": "处理1，再处理5", "state": "可达{0,1,5,6}", "reason": "每个数只能用一次。"}, {"action": "处理11", "state": "f[11]=true", "reason": "单独选11即可，也可由另一些元素组合。"}, {"action": "处理最后5", "state": "1+5+5=11，同样可达", "reason": "返回 true；不同方案不影响布尔结果。"}], "codeNotes": ["f[0]=true：空集合恰好组成0。", "容量倒序：f[j-x]仍是上一轮状态。", "如果目标改成方案数，转移也要改变。"], "trap": "只有一个2、目标4时，正序更新会错误地把同一个2使用两次。", "quiz": {"question": "0/1背包一维压缩为什么倒序？", "options": ["因为数组本身降序", "倒序总比正序快", "防止读取本轮刚更新的状态"], "correct": 2, "why": "二维转移来自上一行，一维必须保留这个依赖关系。"}, "practice": [{"id": "494", "title": "目标和", "url": "https://leetcode.cn/problems/target-sum/", "hint": "把符号分配变成子集和计数，注意0会使方案翻倍。"}, {"id": "1049", "title": "最后一块石头的重量 II", "url": "https://leetcode.cn/problems/last-stone-weight-ii/", "hint": "寻找不超过总和一半的最大可达子集和。"}], "source": "https://leetcode.cn/discuss/post/tXLS3i/", "code": "// 0/1 背包 · 恰好和可达\n// 使用前提：a 中元素非负，target 非负；每个元素至多使用一次。\n// 状态 / 不变量：处理第 i 个元素后，f[j] 表示前 i 个元素能否恰好组成 j。\n// 复杂度：O(n·target) 时间 / O(target) 空间\n\nbool subsetSum(const vector<int>& a,int target) {\n    // 空集合能组成0，其余金额初始不可达。\n    vector<char> f(target+1);f[0]=true;\n    // 倒序容量保证每个元素最多被使用一次。\n    for(int x:a) for(int j=target;j>=x;--j)\n        // 不选x，或从上一轮的j-x选择x转移。\n        f[j]=f[j]||f[j-x];\n    return f[target];\n}", "contract": "a 中元素非负，target 非负；每个元素至多使用一次。", "cost": "O(n·target) 时间 / O(target) 空间"}, {"group": 6, "template": 2, "id": "6-2", "title": "完全背包 · 组合数", "problem": "零钱兑换 II", "problemId": "518", "url": "https://leetcode.cn/problems/coin-change-ii/", "signal": "面额可重复，统计组成金额的组合，忽略使用顺序。", "naive": "递归枚举硬币序列会把1+2与2+1算两遍；按面额分阶段加入。", "invariant": "处理某面额后，f[j] 统计只用已经处理的面额组成 j 的组合数。", "frames": [{"action": "coins=[1,2]，amount=4", "state": "f=[1,0,0,0,0]", "reason": "组成0有一种空方案。", "visual": {"kind": "array", "cells": ["1", "0", "0", "0", "0"], "active": [0, 1, 2, 3, 4], "markers": {}, "caption": "每格是组成下标金额的组合数。"}}, {"action": "处理面额1", "state": "f=[1,1,1,1,1]", "reason": "容量正序，允许重复用1。", "visual": {"kind": "array", "cells": ["1", "1", "1", "1", "1"], "active": [0, 1, 2, 3, 4], "markers": {}, "caption": "每格是组成下标金额的组合数。"}}, {"action": "处理面额2，到j=2、3", "state": "f=[1,1,2,2,1]", "reason": "分别新添[2]和[1,2]。", "visual": {"kind": "array", "cells": ["1", "1", "2", "2", "1"], "active": [0, 1, 2, 3, 4], "markers": {}, "caption": "每格是组成下标金额的组合数。"}}, {"action": "面额2，到j=4", "state": "f[4]=1+f[2]=3", "reason": "三种：1111、112、22。", "visual": {"kind": "array", "cells": ["1", "1", "2", "2", "3"], "active": [0, 1, 2, 3, 4], "markers": {}, "caption": "每格是组成下标金额的组合数。"}}], "codeNotes": ["外层硬币决定组合不重复。", "内层容量正序允许同种硬币多次使用。", "面额要求正数且不重复；大答案需按题意取模或用更大整数。"], "trap": "若外层金额、内层硬币，则通常统计有序排列，不是无序组合。", "quiz": {"question": "改成“凑出金额的最少硬币数”，还能直接累加吗？", "options": ["只需要把顺序倒过来", "不能，应取 min 并重新设置不可达状态", "能，最后减1"], "correct": 1, "why": "状态含义从计数变为最优化，初始化与运算都必须重写。"}, "practice": [{"id": "322", "title": "零钱兑换", "url": "https://leetcode.cn/problems/coin-change/", "hint": "用 INF 表示不可达，转移 min(f[j],f[j-c]+1)。"}, {"id": "377", "title": "组合总和 Ⅳ", "url": "https://leetcode.cn/problems/combination-sum-iv/", "hint": "顺序不同算不同方案，金额外层、数字内层。"}], "source": "https://leetcode.cn/discuss/post/tXLS3i/", "code": "// 完全背包 · 组合数\n// 使用前提：coins 为互不相同的正面额；每种无限使用；结果需能装入 long long。\n// 状态 / 不变量：处理某面额后，f[j] 统计只用已经处理的面额组成 j 的组合数。\n// 复杂度：O(n·amount) 时间 / O(amount) 空间\n\nlong long coinWays(const vector<int>& coins,int amount) {\n    // 组成0有一种空方案，计数初始化不是全0。\n    vector<long long> f(amount+1);f[0]=1;\n    // 硬币外层统计组合；容量正序允许重复取当前硬币。\n    for(int c:coins) for(int j=c;j<=amount;++j) f[j]+=f[j-c];\n    // 答案需在long long范围内，取模题应在转移时取模。\n    return f[amount];\n}", "contract": "coins 为互不相同的正面额；每种无限使用；结果需能装入 long long。", "cost": "O(n·amount) 时间 / O(amount) 空间"}, {"group": 6, "template": 3, "id": "6-3", "title": "双序列 DP · LCS", "problem": "最长公共子序列", "problemId": "1143", "url": "https://leetcode.cn/problems/longest-common-subsequence/", "signal": "两个序列保持原相对顺序，寻找最长共同子序列。", "naive": "枚举两个串的所有子序列是指数级；只需研究最后一个字符是否匹配。", "invariant": "f[i][j] 是 a 的前 i 个字符与 b 的前 j 个字符的 LCS 长度。", "frames": [{"action": "a=abc，b=ac", "state": "第0行、第0列全0", "reason": "任意串与空串的 LCS 为0。", "visual": {"kind": "array", "cells": ["0", "0", "0"], "active": [0, 1, 2], "markers": {}, "caption": "当前DP行，下标表示已使用b的前缀长度。"}}, {"action": "处理 a 的前缀 a", "state": "行 [0,1,1]", "reason": "匹配a后，b再增加c也不能多匹配。", "visual": {"kind": "array", "cells": ["0", "1", "1"], "active": [0, 1, 2], "markers": {}, "caption": "当前DP行，下标表示已使用b的前缀长度。"}}, {"action": "处理前缀 ab", "state": "行 [0,1,1]", "reason": "b没有匹配，只能继承上方或左方。", "visual": {"kind": "array", "cells": ["0", "1", "1"], "active": [0, 1, 2], "markers": {}, "caption": "当前DP行，下标表示已使用b的前缀长度。"}}, {"action": "处理前缀 abc", "state": "行 [0,1,2]", "reason": "c匹配，左上角1再加1，得到ac。", "visual": {"kind": "array", "cells": ["0", "1", "2"], "active": [0, 1, 2], "markers": {}, "caption": "当前DP行，下标表示已使用b的前缀长度。"}}], "codeNotes": ["字符下标用 i-1 与 j-1，对齐长度状态。", "相等取左上+1；不等取上方、左方较大值。", "若压成一行，必须额外保存旧的左上值。"], "trap": "子序列可跳过字符；最长公共子串要求连续，失配时应清零，不能混用。", "quiz": {"question": "abc 与 ac 的最长公共子序列长度？", "options": ["2", "1", "3"], "correct": 0, "why": "可跳过 b，保留 a、c。"}, "practice": [{"id": "583", "title": "两个字符串的删除操作", "url": "https://leetcode.cn/problems/delete-operation-for-two-strings/", "hint": "删除次数为 n+m-2×LCS。"}, {"id": "72", "title": "编辑距离", "url": "https://leetcode.cn/problems/edit-distance/", "hint": "编辑距离需区分插入、删除、替换，取最小值。"}], "source": "https://leetcode.cn/discuss/post/tXLS3i/", "code": "// 双序列 DP · LCS\n// 使用前提：f[i][j] 表示两个前缀的最长公共子序列长度。\n// 状态 / 不变量：f[i][j] 是 a 的前 i 个字符与 b 的前 j 个字符的 LCS 长度。\n// 复杂度：O(nm) 时间 / O(nm) 空间\n\nint lcs(const string& a,const string& b) {\n    int n=a.size(),m=b.size();\n    // 额外的第0行、第0列代表空前缀。\n    vector<vector<int>> f(n+1,vector<int>(m+1));\n    // 状态i,j是前缀长度，字符下标要减1。\n    for(int i=1;i<=n;++i) for(int j=1;j<=m;++j)\n        // 相等延长左上状态；不等则分别跳过一边。\n        f[i][j]=a[i-1]==b[j-1]?f[i-1][j-1]+1:max(f[i-1][j],f[i][j-1]);\n    return f[n][m];\n}", "contract": "f[i][j] 表示两个前缀的最长公共子序列长度。", "cost": "O(nm) 时间 / O(nm) 空间"}, {"group": 7, "template": 0, "id": "7-0", "title": "前缀和 + 哈希计数", "problem": "和为 K 的子数组", "problemId": "560", "url": "https://leetcode.cn/problems/subarray-sum-equals-k/", "signal": "连续区间和等于 k，数组可含负数。", "naive": "正负数混合时收缩窗口无法单调控制和；把区间和改写为两个前缀的差。", "invariant": "处理当前前缀 S 时，freq 只存它之前的前缀和出现次数。", "frames": [{"action": "nums=[1,-1,1]，k=1", "state": "freq={0:1} / ans=0", "reason": "空前缀使从下标0开始的区间可被统计。"}, {"action": "读第一个1", "state": "S=1 / 查0得1 / ans=1", "reason": "先查询，再登记前缀1。"}, {"action": "读-1", "state": "S=0 / 查-1得0 / ans=1", "reason": "前缀0的频次变为2。"}, {"action": "读最后1", "state": "S=1 / 查0得2 / ans=3", "reason": "对应最后一个1，以及整个区间。"}], "codeNotes": ["找 prefix-k，而不是 k-prefix。", "频次而非集合：同一个前缀和可能出现多次。", "查询在增加当前前缀频次之前。"], "trap": "k=0 时先登记会把长度0的区间也算进去。", "quiz": {"question": "为什么 freq[0] 初始设为1？", "options": ["说明数组必有一个0", "避免哈希表为空", "代表数组开始前的空前缀"], "correct": 2, "why": "它不是虚构元素，而是前缀和差公式的边界。"}, "practice": [{"id": "974", "title": "和可被 K 整除的子数组", "url": "https://leetcode.cn/problems/subarray-sums-divisible-by-k/", "hint": "保存前缀和对 k 的归一化余数。"}, {"id": "525", "title": "连续数组", "url": "https://leetcode.cn/problems/contiguous-array/", "hint": "把0映射为-1，问题变为和为0的最长区间。"}], "source": "https://leetcode.cn/discuss/post/mOr1u6/", "code": "// 前缀和 + 哈希计数\n// 使用前提：允许负数；哈希时间复杂度按平均情况计算。\n// 状态 / 不变量：处理当前前缀 S 时，freq 只存它之前的前缀和出现次数。\n// 复杂度：平均 O(n) 时间 / O(n) 空间\n\nlong long subarraySum(const vector<int>& a,long long k) {\n    // 空前缀出现一次，使从下标0开始的区间也能被统计。\n    unordered_map<long long,long long> freq;freq[0]=1;\n    long long prefix=0,answer=0;\n    for(int x:a) {\n        prefix+=x;\n        // 旧前缀必须等于当前前缀-k，二者差才为k。\n        auto it=freq.find(prefix-k);\n        if(it!=freq.end()) answer+=it->second;\n        // 先查再登记，避免k=0时误计长度0的区间。\n        ++freq[prefix];\n    }\n    return answer;\n}", "contract": "允许负数；哈希时间复杂度按平均情况计算。", "cost": "平均 O(n) 时间 / O(n) 空间"}, {"group": 7, "template": 1, "id": "7-1", "title": "并查集 · 路径压缩 + 按大小合并", "problem": "省份数量", "problemId": "547", "url": "https://leetcode.cn/problems/number-of-provinces/", "signal": "不断合并集合，并查询两个节点是否连通。", "naive": "每次查询都 DFS 代价大；用代表元维护连通关系。", "invariant": "每个集合恰有一个根，find(x) 返回根；合并只改变两个根的关系。", "frames": [{"action": "4个点，边(0,1)、(2,3)", "state": "根 [0,1,2,3] / 分量4", "reason": "初始每个点独立。"}, {"action": "合并0、1", "state": "{0,1} / {2} / {3}，分量3", "reason": "小集合根挂到大集合根。"}, {"action": "合并2、3", "state": "{0,1} / {2,3}，分量2", "reason": "这是一个通用连通示例；省份题对矩阵中的1执行合并。"}, {"action": "再合并1、0", "state": "根已相同，分量仍2", "reason": "重复边不会产生新的连通分量变化。"}], "codeNotes": ["find 路径压缩：把沿途节点直接挂到根。", "按 size 合并避免退化长链。", "unite 返回 false 表示已在同一集合。"], "trap": "并查集不保存实际路径，也不直接支持删边后的拆分。", "quiz": {"question": "边加入前两端已连通，是否增加连通性？", "options": ["必须重建所有集合", "不增加，unite返回false", "分量数减1"], "correct": 1, "why": "无向图中这条边还可能形成环，但不改变连通分量。"}, "practice": [{"id": "684", "title": "冗余连接", "url": "https://leetcode.cn/problems/redundant-connection/", "hint": "首条连接同集合两端的边就是候选冗余边。"}, {"id": "1319", "title": "连通网络的操作次数", "url": "https://leetcode.cn/problems/number-of-operations-to-make-network-connected/", "hint": "统计分量和多余边，判断能否连接全图。"}], "source": "https://leetcode.cn/discuss/post/mOr1u6/", "code": "// 并查集 · 路径压缩 + 按大小合并\n// 使用前提：编号 0..n−1；不支持直接删除边。\n// 状态 / 不变量：每个集合恰有一个根，find(x) 返回根；合并只改变两个根的关系。\n// 复杂度：单次均摊 O(α(n)) / O(n) 空间\n\nstruct DSU {\n    vector<int> p,size;\n    explicit DSU(int n):p(n),size(n,1) {iota(p.begin(),p.end(),0);}\n    // 路径压缩：沿途节点直接指向集合代表元。\n    int find(int x) {return p[x]==x?x:p[x]=find(p[x]);}\n    bool unite(int a,int b) {\n        // 必须先找根，再判断是否已在同一个集合。\n        a=find(a);b=find(b);if(a==b) return false;\n        if(size[a]<size[b]) swap(a,b);\n        // 小集合挂到大集合，并更新新根的大小。\n        p[b]=a;size[a]+=size[b];return true;\n    }\n};", "contract": "编号 0..n−1；不支持直接删除边。", "cost": "单次均摊 O(α(n)) / O(n) 空间"}, {"group": 7, "template": 2, "id": "7-2", "title": "树状数组 · 单点增量与前缀和", "problem": "区域和检索 - 数组可修改", "problemId": "307", "url": "https://leetcode.cn/problems/range-sum-query-mutable/", "signal": "数组频繁单点修改，同时查询区间和。", "naive": "静态前缀和查询快，但每次更新需重算后缀；树状数组兼顾两者。", "invariant": "内部 tree[i] 管理以 i 结尾、长度 lowbit(i) 的一段，内部下标从1开始。", "frames": [{"action": "a=[1,3,5]", "state": "prefix(3)=9 / range(0,3)=9", "reason": "对外区间采用左闭右开。"}, {"action": "把 a[1] 从3改为2", "state": "delta=-1 / add(1,-1)", "reason": "更新传入增量，不是新的绝对值。"}, {"action": "更新内部节点2", "state": "tree[2] 减1", "reason": "内部 i=pos+1=2，然后跳到4超界。"}, {"action": "再次查询[0,3)", "state": "prefix路径3→2→0 / 结果8", "reason": "几个互不重叠的块合并成前缀。"}], "codeNotes": ["add 使用 i+=i&-i 跳到包含当前块的父块。", "prefix(r) 累加 [0,r)；内部查询 i-=i&-i。", "平台常给闭区间[l,r]，应调用 range(l,r+1)。"], "trap": "把新值直接作为 delta，会把赋值操作错误地变成累加。", "quiz": {"question": "旧值7改成4，add应该传多少？", "options": ["-3", "4", "7"], "correct": 0, "why": "保存原数组值，用 new-old 计算增量，再更新原数组。"}, "practice": [{"id": "307", "title": "区域和检索 - 数组可修改", "url": "https://leetcode.cn/problems/range-sum-query-mutable/", "hint": "写一层 update 包装，保留旧值来计算 delta。"}, {"id": "315", "title": "计算右侧小于当前元素的个数", "url": "https://leetcode.cn/problems/count-of-smaller-numbers-after-self/", "hint": "离散化数值，从右往左统计更小值的频次。"}], "source": "https://leetcode.cn/discuss/post/mOr1u6/", "code": "// 树状数组 · 单点增量与前缀和\n// 使用前提：外部下标从 0 开始。prefix(r) 返回 [0,r)；range(l,r) 返回 [l,r)。\n// 状态 / 不变量：内部 tree[i] 管理以 i 结尾、长度 lowbit(i) 的一段，内部下标从1开始。\n// 复杂度：单次 O(log n) 时间 / O(n) 空间\n\nstruct Fenwick {\n    int n;vector<long long> tree;\n    explicit Fenwick(int n):n(n),tree(n+1) {}\n    // 对外pos从0开始；内部从1开始，delta是增量。\n    void add(int pos,long long delta) {\n        for(int i=pos+1;i<=n;i+=i&-i) tree[i]+=delta;\n    }\n    // 查询半开区间[0,r)，沿lowbit向前拆分。\n    long long prefix(int r) const {\n        long long sum=0;\n        for(int i=r;i>0;i-=i&-i) sum+=tree[i];\n        return sum;\n    }\n    // 半开区间[l,r)之和等于两个前缀之差。\n    long long range(int l,int r) const {return prefix(r)-prefix(l);}\n};", "contract": "外部下标从 0 开始。prefix(r) 返回 [0,r)；range(l,r) 返回 [l,r)。", "cost": "单次 O(log n) 时间 / O(n) 空间"}, {"group": 8, "template": 0, "id": "8-0", "title": "埃氏筛 · 统计小于 n 的质数", "problem": "计数质数", "problemId": "204", "url": "https://leetcode.cn/problems/count-primes/", "signal": "统计一个上界内的全部质数，允许 O(n) 标记空间。", "naive": "逐个试除到平方根需约 O(n√n)；质数的倍数可以批量标记。", "invariant": "遇到未标记的 p，它不含更小质因子，因此是质数。", "frames": [{"action": "求小于10的质数", "state": "0、1不进入质数循环", "reason": "范围不含10。"}, {"action": "p=2", "state": "计数1，标记4、6、8", "reason": "从 p² 开始，更小倍数已有更小因子。"}, {"action": "p=3", "state": "计数2，标记9", "reason": "6已由2处理，不必重复从2p开始。"}, {"action": "继续到9", "state": "计入5、7 / 答案4", "reason": "4、6、8、9跳过。"}], "codeNotes": ["p 从2开始，严格 p<n。", "j 使用 long long，避免 p*p 溢出。", "未标记就计数；即使 p²≥n，它本身仍可能是质数。"], "trap": "题目是“小于 n”，不要把 n 也计入。大 n 时还需考虑空间。", "quiz": {"question": "n=2 时答案是多少？", "options": ["2", "0", "1"], "correct": 1, "why": "唯一候选质数2不在严格小于2的范围内。"}, "practice": [{"id": "2523", "title": "范围内最接近的两个质数", "url": "https://leetcode.cn/problems/closest-prime-numbers-in-range/", "hint": "筛出区间内质数，再比较相邻质数差。"}, {"id": "2601", "title": "质数减法运算", "url": "https://leetcode.cn/problems/prime-subtraction-operation/", "hint": "预处理质数后再考虑每步可减哪个质数。"}], "source": "https://leetcode.cn/discuss/post/IYT3ss/", "code": "// 埃氏筛 · 统计小于 n 的质数\n// 使用前提：n ≥ 0；结果不包含 n。\n// 状态 / 不变量：遇到未标记的 p，它不含更小质因子，因此是质数。\n// 复杂度：O(n log log n) 时间 / O(n) 空间\n\nint countPrimes(int n) {\n    vector<char> composite(n);int count=0;\n    // 枚举范围严格小于n；0和1不是质数。\n    for(int p=2;p<n;++p) {\n        // 被更小质因子标记过的数是合数。\n        if(composite[p]) continue;\n        ++count;\n        // 从p平方开始；更小倍数已经处理，乘法用long long。\n        for(long long j=1LL*p*p;j<n;j+=p) composite[(int)j]=true;\n    }\n    return count;\n}", "contract": "n ≥ 0；结果不包含 n。", "cost": "O(n log log n) 时间 / O(n) 空间"}, {"group": 8, "template": 1, "id": "8-1", "title": "快速幂 · 模整数", "problem": "统计好数字的数目", "problemId": "1922", "url": "https://leetcode.cn/problems/count-good-numbers/", "signal": "指数很大，要求整数幂取模，乘法结合律成立。", "naive": "逐次乘 x 需要 O(e)，把指数按二进制拆开只需 O(log e)。", "invariant": "循环中 ans × x^e 与原始目标在模意义下相同。", "frames": [{"action": "演示 3^5 mod 100", "state": "ans=1 / x=3 / e=5", "reason": "5的二进制是101。"}, {"action": "最低位为1", "state": "ans=3 / x=9 / e=2", "reason": "把一个3取进答案，剩余指数折半。"}, {"action": "最低位为0", "state": "ans=3 / x=81 / e=1", "reason": "只平方基数，不乘答案。"}, {"action": "最低位为1", "state": "ans=43 / e=0", "reason": "3×81 mod100=43。好数字计数分别计算5与4的幂。"}], "codeNotes": ["e&1 时乘入当前基数。", "x=x*x%mod；e>>=1，同时推进。", "1922 用 5^ceil(n/2) × 4^floor(n/2)，再取模。"], "trap": "long long 并非无限大。模板限定模数≤2^31−1，超过范围需安全模乘。", "quiz": {"question": "为什么不能用浮点 pow 再取模？", "options": ["大整数会丢精度或溢出", "浮点只支持偶数指数", "取模没有结合律"], "correct": 0, "why": "模运算必须在整数乘法过程中进行。"}, "practice": [{"id": "372", "title": "超级次方", "url": "https://leetcode.cn/problems/super-pow/", "hint": "按十进制指数逐位合成，不必把指数转为整数。"}, {"id": "2550", "title": "猴子碰撞的方法数", "url": "https://leetcode.cn/problems/count-collisions-of-monkeys-on-a-polygon/", "hint": "计算2^n再减去两种特殊情况，负余数需归一化。"}], "source": "https://leetcode.cn/discuss/post/IYT3ss/", "code": "// 快速幂 · 模整数\n// 使用前提：e ≥ 0，1 ≤ mod ≤ 2^31−1；此范围保证中间乘积适合 long long。\n// 状态 / 不变量：循环中 ans × x^e 与原始目标在模意义下相同。\n// 复杂度：O(log e) 时间 / O(1) 空间\n\nlong long modPow(long long x,long long e,long long mod) {\n    x=(x%mod+mod)%mod;\n    // 指数为0时返回1 mod mod；mod=1也能正确处理。\n    long long ans=1%mod;\n    while(e) {\n        // 当前二进制位为1，才把这一幂贡献乘入答案。\n        if(e&1) ans=ans*x%mod;\n        // 基数平方、指数右移，保持ans×x^e不变。\n        x=x*x%mod;e>>=1;\n    }\n    return ans;\n}", "contract": "e ≥ 0，1 ≤ mod ≤ 2^31−1；此范围保证中间乘积适合 long long。", "cost": "O(log e) 时间 / O(1) 空间"}, {"group": 9, "template": 0, "id": "9-0", "title": "按结束时间选区间", "problem": "无重叠区间", "problemId": "435", "url": "https://leetcode.cn/problems/non-overlapping-intervals/", "signal": "保留最多互不重叠区间，所有区间价值相同。", "naive": "枚举保留集合指数级；结束越早，留给后面的空间越大。", "invariant": "把任一最优解首段换成最早结束段，不会挡住它后面的区间。", "frames": [{"action": "区间 [1,2],[1,3],[2,3],[3,4]", "state": "按右端点排序", "reason": "同右端点顺序不影响最多数量。"}, {"action": "选择[1,2]", "state": "end=2 / keep=1", "reason": "最早结束。"}, {"action": "跳过[1,3]，选择[2,3]", "state": "end=3 / keep=2", "reason": "端点相接允许，所以用 ≥。"}, {"action": "选择[3,4]", "state": "keep=3 / 删除数=4-3=1", "reason": "目标从最少删除转为最多保留。"}], "codeNotes": ["排序比较 right，不是 left 或长度。", "left>=end 才可接上。", "返回总数减 keep。"], "trap": "若区间带权，最多数量与最大权值不同，通常需带二分的 DP。", "quiz": {"question": "结束最早的策略靠什么保证正确？", "options": ["交换后不会减少后续可选区间", "直觉上最短", "只在样例上正确"], "correct": 0, "why": "要证明能把某个最优解改成含贪心选择的最优解。"}, "practice": [{"id": "452", "title": "用最少数量的箭引爆气球", "url": "https://leetcode.cn/problems/minimum-number-of-arrows-to-burst-balloons/", "hint": "气球端点相接可共用一箭，比较符号需要重新检查。"}, {"id": "1235", "title": "规划兼职工作", "url": "https://leetcode.cn/problems/maximum-profit-in-job-scheduling/", "hint": "带收益的区间调度不能照搬计数贪心，应改DP。"}], "source": "https://leetcode.cn/discuss/post/g6KTKL/", "code": "// 按结束时间选区间\n// 使用前提：区间左右端点合法，端点接触视为不重叠。\n// 状态 / 不变量：把任一最优解首段换成最早结束段，不会挡住它后面的区间。\n// 复杂度：O(n log n) 时间 / 排序递归栈 O(log n)\n\nint eraseOverlap(vector<pair<int,int>> intervals) {\n    // 结束越早，为后续区间保留的空间越大。\n    sort(intervals.begin(),intervals.end(),[](auto a,auto b){return a.second<b.second;});\n    // 初始不设限制；端点接触允许，因此用>=。\n    long long end=LLONG_MIN;int keep=0;\n    for(auto seg:intervals) if(seg.first>=end) {++keep;end=seg.second;}\n    // 最少删除数=总数-最多保留数。\n    return (int)intervals.size()-keep;\n}", "contract": "区间左右端点合法，端点接触视为不重叠。", "cost": "O(n log n) 时间 / 排序递归栈 O(log n)"}, {"group": 9, "template": 1, "id": "9-1", "title": "反悔贪心 · 最多课程", "problem": "课程表 III", "problemId": "630", "url": "https://leetcode.cn/problems/course-schedule-iii/", "signal": "按截止时间安排尽量多任务，允许撤回先前选择。", "naive": "只选短课可能错过早截止的课；先按截止排序，再维护最省时的候选集合。", "invariant": "处理到当前截止时间时，所选课程可按截止顺序完成；超时撤掉最长课，最大程度释放时间。", "frames": [{"action": "课程(耗时,截止)=(3,3),(2,4),(2,5)", "state": "按截止已排序 / total=0", "reason": "维护所选时长的大根堆。"}, {"action": "加入(3,3)", "state": "total=3 / 堆[3]", "reason": "可按时完成。"}, {"action": "加入(2,4)", "state": "total=5>4，撤3 / total=2", "reason": "课数仍1，但留下更小总耗时。"}, {"action": "加入(2,5)", "state": "total=4 / 选2门", "reason": "保留两门耗时2的课。"}], "codeNotes": ["排序是截止时间，不是时长。", "先加入，再超时则弹最大时长。", "每次最多移除一个：移除值≥刚加入时长，可恢复此前可行性。"], "trap": "小根堆会撤掉最短课，反而保留更多占用时间，削弱未来选择。", "quiz": {"question": "撤回哪门课程最有利于后续安排？", "options": ["截止最早的", "刚加入的，永远如此", "已选课程中耗时最长的"], "correct": 2, "why": "最长课可能是旧课，也可能是新课。"}, "practice": [{"id": "871", "title": "最低加油次数", "url": "https://leetcode.cn/problems/minimum-number-of-refueling-stops/", "hint": "先走到可达位置，需要补油时从经过的站选最多油量。"}, {"id": "1642", "title": "可以到达的最远建筑", "url": "https://leetcode.cn/problems/furthest-building-you-can-reach/", "hint": "梯子留给最大跨越，其他用砖；用堆维护分配。"}], "source": "https://leetcode.cn/discuss/post/g6KTKL/", "code": "// 反悔贪心 · 最多课程\n// 使用前提：每项为 {时长,截止日期}，时长为正；同一时间只学一门课。\n// 状态 / 不变量：处理到当前截止时间时，所选课程可按截止顺序完成；超时撤掉最长课，最大程度释放时间。\n// 复杂度：O(n log n) 时间 / O(n) 空间\n\nint scheduleCourses(vector<pair<int,int>> courses) {\n    // 先按截止时间排序，保证前缀任务的可行性。\n    sort(courses.begin(),courses.end(),[](auto a,auto b){return a.second<b.second;});\n    priority_queue<int> used;long long total=0;\n    for(auto c:courses) {\n        // 先接纳当前课，大根堆记录所有已选时长。\n        total+=c.first;used.push(c.first);\n        // 超时就撤最长课；可能撤掉当前课，也可能是旧课。\n        if(total>c.second) {total-=used.top();used.pop();}\n    }\n    return used.size();\n}", "contract": "每项为 {时长,截止日期}，时长为正；同一时间只学一门课。", "cost": "O(n log n) 时间 / O(n) 空间"}, {"group": 10, "template": 0, "id": "10-0", "title": "原地反转链表", "problem": "反转链表", "problemId": "206", "url": "https://leetcode.cn/problems/reverse-linked-list/", "signal": "单链表原地反转，只改 next 指向。", "naive": "借助数组可以反转，但要额外空间；三个指针即可维护处理边界。", "invariant": "prev 指向已反转前缀，cur 指向尚未处理后缀，两个部分覆盖原链表。", "frames": [{"action": "链表 1→2→3", "state": "prev=null / cur=1", "reason": "开始时已反转前缀为空。"}, {"action": "保存next=2，反转1", "state": "prev=1→null / cur=2", "reason": "先保存后继，再修改链接。"}, {"action": "保存next=3，反转2", "state": "prev=2→1→null / cur=3", "reason": "前缀增长一个节点。"}, {"action": "反转3", "state": "prev=3→2→1 / cur=null", "reason": "返回prev，它就是新头。"}], "codeNotes": ["next=cur->next 必须先执行。", "cur->next=prev 是实际反转动作。", "prev=cur; cur=next 推进边界。"], "trap": "只移动指针不改 next，不会反转；改 next 后再找后继，会丢失原后缀。", "quiz": {"question": "空链表传入后返回什么？", "options": ["一个新节点", "必须报错", "nullptr"], "correct": 2, "why": "循环不进入，prev保持空，无需特殊分配。"}, "practice": [{"id": "92", "title": "反转链表 II", "url": "https://leetcode.cn/problems/reverse-linked-list-ii/", "hint": "只反转中间一段，记录前驱和尾部连接点。"}, {"id": "25", "title": "K 个一组翻转链表", "url": "https://leetcode.cn/problems/reverse-nodes-in-k-group/", "hint": "先确认剩余至少 k 个节点，再整组反转。"}], "source": "https://leetcode.cn/discuss/post/K0n2gO/", "code": "// 原地反转链表\n// 使用前提：ListNode 定义见下方代码；只改变链接，不分配或释放节点。\n// 状态 / 不变量：prev 指向已反转前缀，cur 指向尚未处理后缀，两个部分覆盖原链表。\n// 复杂度：O(n) 时间 / O(1) 空间\n\n// 改链接之前先保存原后继，否则会丢失后面的链。\nstruct ListNode {int val;ListNode* next;};\nListNode* reverseList(ListNode* head) {\n    // prev是已反转前缀，cur是未处理后缀的头。\n    ListNode *prev=nullptr,*cur=head;\n    while(cur) {\n        ListNode* next=cur->next;\n        // 完成反向链接后，再推进处理边界。\n        cur->next=prev;prev=cur;cur=next;\n    }\n    return prev;\n}", "contract": "ListNode 定义见下方代码；只改变链接，不分配或释放节点。", "cost": "O(n) 时间 / O(1) 空间"}, {"group": 10, "template": 1, "id": "10-1", "title": "后序递归 · 树高", "problem": "二叉树的最大深度", "problemId": "104", "url": "https://leetcode.cn/problems/maximum-depth-of-binary-tree/", "signal": "树的答案可从左右子树的同类答案合成。", "naive": "先明确递归返回值，避免在不同层混用节点数和边数。", "invariant": "height(node) 返回以该节点为根的子树节点层数，空树为0。", "frames": [{"action": "根1，左叶2，右子树3→4", "state": "先进入左右子树", "reason": "父节点需要两个子结果才能结算。"}, {"action": "叶2与叶4", "state": "两边空树都为0，叶高度=1", "reason": "递归终止于空指针。"}, {"action": "回到节点3", "state": "max(0,1)+1=2", "reason": "只取较长的一侧向上延伸。"}, {"action": "回到根1", "state": "max(1,2)+1=3", "reason": "整树高度3层。"}], "codeNotes": ["if(!root) return 0 是边界。", "左右递归求的是相同含义。", "父节点增加1层，得到自身高度。"], "trap": "树高为 h 时栈空间 O(h)，退化链表为 O(n)，不是总能 O(log n)。", "quiz": {"question": "求树的直径时能直接把根的高度当答案吗？", "options": ["只能减1", "不能，最长路径可能跨两侧或不经过根", "能，直径总等于高度"], "correct": 1, "why": "直径需在每个节点合并左右高度，并取全局最大。"}, "practice": [{"id": "110", "title": "平衡二叉树", "url": "https://leetcode.cn/problems/balanced-binary-tree/", "hint": "高度计算同时检查左右差，及时传播不平衡。"}, {"id": "543", "title": "二叉树的直径", "url": "https://leetcode.cn/problems/diameter-of-binary-tree/", "hint": "返回高度，另外更新左右高度之和。"}], "source": "https://leetcode.cn/discuss/post/K0n2gO/", "code": "// 后序递归 · 树高\n// 使用前提：空树高度 0；极深树应改用显式栈，防止调用栈溢出。\n// 状态 / 不变量：height(node) 返回以该节点为根的子树节点层数，空树为0。\n// 复杂度：O(n) 时间 / O(树高) 栈空间\n\nstruct TreeNode {int val;TreeNode *left,*right;};\nint treeHeight(TreeNode* root) {\n    // 空树高度为0，叶子最终会得到高度1。\n    if(!root) return 0;\n    // 高度按节点层数计算：较高子树再加当前节点。\n    return 1+max(treeHeight(root->left),treeHeight(root->right));\n}", "contract": "空树高度 0；极深树应改用显式栈，防止调用栈溢出。", "cost": "O(n) 时间 / O(树高) 栈空间"}, {"group": 10, "template": 2, "id": "10-2", "title": "选或不选 · 子集", "problem": "子集", "problemId": "78", "url": "https://leetcode.cn/problems/subsets/", "signal": "枚举所有选择方案，每个元素可以选或不选。", "naive": "结果本来就有2^n个，重点是避免遗漏、重复和状态污染。", "invariant": "进入 dfs(i) 时，path 只包含前 i 个元素中已经选择的元素。", "frames": [{"action": "输入 [1,2]，dfs(0)", "state": "path=[]", "reason": "每层决定一个元素。"}, {"action": "不选1，继续决定2", "state": "输出[]、[2]", "reason": "每到 i=n 才保存路径。"}, {"action": "选1，继续决定2", "state": "输出[1]、[1,2]", "reason": "选择2后要撤销2。"}, {"action": "回到根", "state": "path恢复为空", "reason": "每次 push 对应一次 pop，兄弟分支不串数据。"}], "codeNotes": ["i==a.size()：一套完整决策结束。", "先不选，再 push 后递归。", "pop_back 恢复进入当前分支之前的状态。"], "trap": "含重复元素时，按下标枚举会产生相同值集合，需要排序去重的另一套规则。", "quiz": {"question": "保存答案后若不撤销选择，会怎样？", "options": ["后续分支带上不属于自己的元素", "只是答案顺序不同", "能自动去重"], "correct": 0, "why": "回溯操作是一种共享状态，必须显式恢复。"}, "practice": [{"id": "77", "title": "组合", "url": "https://leetcode.cn/problems/combinations/", "hint": "只收集大小为k的路径，并按剩余数量剪枝。"}, {"id": "90", "title": "子集 II", "url": "https://leetcode.cn/problems/subsets-ii/", "hint": "排序后按层跳过重复值，防止同值子集重复。"}], "source": "https://leetcode.cn/discuss/post/K0n2gO/", "code": "// 选或不选 · 子集\n// 使用前提：a 中元素互不相同；含重复元素时需要排序并去重。\n// 状态 / 不变量：进入 dfs(i) 时，path 只包含前 i 个元素中已经选择的元素。\n// 复杂度：O(n·2^n) 时间 / O(n) 辅助栈，不含输出\n\nvector<vector<int>> subsets(const vector<int>& a) {\n    vector<vector<int>> ans;vector<int> path;\n    function<void(int)> dfs=[&](int i) {\n        // 所有元素都决定完毕，复制当前路径存入答案。\n        if(i==(int)a.size()) {ans.push_back(path);return;}\n        // 第一条分支不选当前元素。\n        dfs(i+1);\n        // 第二条分支选择当前元素；递归结束后撤销选择。\n        path.push_back(a[i]);dfs(i+1);path.pop_back();\n    };\n    dfs(0);return ans;\n}", "contract": "a 中元素互不相同；含重复元素时需要排序并去重。", "cost": "O(n·2^n) 时间 / O(n) 辅助栈，不含输出"}, {"group": 11, "template": 0, "id": "11-0", "title": "KMP · 首次匹配位置", "problem": "找出字符串中第一个匹配项的下标", "problemId": "28", "url": "https://leetcode.cn/problems/find-the-index-of-the-first-occurrence-in-a-string/", "signal": "单模式匹配，失配后希望复用已知相等的前后缀。", "naive": "每个起点重新匹配最坏 O(nm)；已匹配部分的 border 指出下一候选长度。", "invariant": "j 是已读主串后缀与模式前缀的最长匹配长度。", "frames": [{"action": "text=ababc，pattern=abc", "state": "pi=[0,0,0] / j=0", "reason": "模式没有非空相等前后缀。"}, {"action": "读主串 a、b", "state": "j=2", "reason": "已匹配 ab。"}, {"action": "再读 a，与 c 失配", "state": "j=pi[1]=0，再匹配a，j=1", "reason": "主串位置不回退，当前字符要再次比较。"}, {"action": "继续 b、c", "state": "j=3，起点=4-3+1=2", "reason": "匹配成功返回起点2。"}], "codeNotes": ["构造pi与主串匹配遵守同一套长度定义。", "失配 while(j>0) 回退到 pi[j-1]。", "匹配长度等于模式长度，返回当前位置减长度加1。"], "trap": "不能把其他资料中“下标型 next=-1”的写法与本模板长度型 pi 混用。", "quiz": {"question": "失配后为什么不用把主串指针退回？", "options": ["模式必须已排序", "前缀信息已排除不可能的起点", "主串从不重复"], "correct": 1, "why": "利用已知相等关系移动模式的候选起点即可。"}, "practice": [{"id": "459", "title": "重复的子字符串", "url": "https://leetcode.cn/problems/repeated-substring-pattern/", "hint": "用最后一个pi值推导最短候选周期，并检查整除。"}, {"id": "1392", "title": "最长快乐前缀", "url": "https://leetcode.cn/problems/longest-happy-prefix/", "hint": "最长相等真前后缀的长度就是末尾pi。"}], "source": "https://leetcode.cn/discuss/post/SJFwQI/", "code": "// KMP · 首次匹配位置\n// 使用前提：按字节匹配；空模式约定匹配位置 0。\n// 状态 / 不变量：j 是已读主串后缀与模式前缀的最长匹配长度。\n// 复杂度：O(n+m) 时间 / O(m) 空间\n\nint kmpFind(const string& text,const string& pattern) {\n    int m=pattern.size();if(m==0) return 0;\n    // pi[i]记录模式前缀的最长相等真前后缀长度。\n    vector<int> pi(m);\n    for(int i=1,j=0;i<m;++i) {\n        while(j>0&&pattern[i]!=pattern[j]) j=pi[j-1];\n        if(pattern[i]==pattern[j]) ++j;\n        pi[i]=j;\n    }\n    for(int i=0,j=0;i<(int)text.size();++i) {\n        // 失配按已知border回退；主串指针不后退。\n        while(j>0&&text[i]!=pattern[j]) j=pi[j-1];\n        if(text[i]==pattern[j]) ++j;\n        // 匹配长度达到m，当前下标是终点，换算成起点。\n        if(j==m) return i-m+1;\n    }\n    return -1;\n}", "contract": "按字节匹配；空模式约定匹配位置 0。", "cost": "O(n+m) 时间 / O(m) 空间"}, {"group": 11, "template": 1, "id": "11-1", "title": "Z 函数 · 前缀匹配长度", "problem": "构造字符串的总得分和", "problemId": "2223", "url": "https://leetcode.cn/problems/sum-of-scores-of-built-strings/", "signal": "对每个后缀求它与整个串前缀的最长匹配长度。", "naive": "每个后缀从头比较最坏 O(n²)；已知匹配区间可以提供下界。", "invariant": "维护已知与前缀匹配的最右区间 [l,r)，区间内先复用 z[i-l]。", "frames": [{"action": "s=ababa，约定z[0]=0", "state": "z=[0,0,0,0,0]", "reason": "2223题中完整字符串的贡献长度 n 要另加。", "visual": {"kind": "array", "cells": ["0", "0", "0", "0", "0"], "active": [0, 1, 2, 3, 4], "markers": {}, "caption": "z数组；尚未计算的位置暂显示0，z[0]约定为0。"}}, {"action": "i=1", "state": "b不等于a / z[1]=0", "reason": "从空匹配开始。", "visual": {"kind": "array", "cells": ["0", "0", "0", "0", "0"], "active": [0, 1, 2, 3, 4], "markers": {}, "caption": "z数组；尚未计算的位置暂显示0，z[0]约定为0。"}}, {"action": "i=2", "state": "aba匹配前缀 / z[2]=3 / [l,r)=[2,5)", "reason": "得到新的最右匹配盒。", "visual": {"kind": "array", "cells": ["0", "0", "3", "0", "0"], "active": [0, 1, 2, 3, 4], "markers": {}, "caption": "z数组；尚未计算的位置暂显示0，z[0]约定为0。"}}, {"action": "i=3、4", "state": "z[3]=0，z[4]=1 / 总分=5+3+1=9", "reason": "区间内复用，但不能超过 r-i。", "visual": {"kind": "array", "cells": ["0", "0", "3", "0", "1"], "active": [0, 1, 2, 3, 4], "markers": {}, "caption": "z数组；尚未计算的位置暂显示0，z[0]约定为0。"}}], "codeNotes": ["i<r 时先取 min(r-i,z[i-l])。", "while 只对未知部分继续比较。", "i+z[i]>r 时更新最右区间。"], "trap": "z[i]不是“以i结尾”的前后缀长度，那是另一种量；本模板 z[0]=0。", "quiz": {"question": "s=aaaa 的 z 数组是什么？", "options": ["[0,3,2,1]", "[1,2,3,4]", "[0,0,0,0]"], "correct": 0, "why": "每个后缀都是前缀，长度逐一减少。"}, "practice": [{"id": "2223", "title": "构造字符串的总得分和", "url": "https://leetcode.cn/problems/sum-of-scores-of-built-strings/", "hint": "求和时补上整个字符串长度 n。"}, {"id": "28", "title": "找出字符串中第一个匹配项的下标", "url": "https://leetcode.cn/problems/find-the-index-of-the-first-occurrence-in-a-string/", "hint": "构造 pattern+分隔符+text，分隔符需不在输入字符集中。"}], "source": "https://leetcode.cn/discuss/post/SJFwQI/", "code": "// Z 函数 · 前缀匹配长度\n// 使用前提：z[0] 约定为 0；维护已知匹配区间 [l,r)。\n// 状态 / 不变量：维护已知与前缀匹配的最右区间 [l,r)，区间内先复用 z[i-l]。\n// 复杂度：O(n) 时间 / O(n) 空间\n\nvector<int> zFunction(const string& s) {\n    int n=s.size();vector<int> z(n);\n    for(int i=1,l=0,r=0;i<n;++i) {\n        // 位于匹配盒内，复用已知值但不能超过右边界。\n        if(i<r) z[i]=min(r-i,z[i-l]);\n        // 仅对未知部分继续向右比较。\n        while(i+z[i]<n&&s[z[i]]==s[i+z[i]]) ++z[i];\n        // 如果到达更右位置，更新半开匹配盒[l,r)。\n        if(i+z[i]>r) {l=i;r=i+z[i];}\n    }\n    return z;\n}", "contract": "z[0] 约定为 0；维护已知匹配区间 [l,r)。", "cost": "O(n) 时间 / O(n) 空间"}, {"group": 0, "template": 2, "id": "0-2", "title": "最短窗口 · 达到目标和", "problem": "长度最小的子数组", "problemId": "209", "url": "https://leetcode.cn/problems/minimum-size-subarray-sum/", "signal": "求和至少 target 的最短连续区间，正数保证缩短后和减小。", "naive": "暴力枚举端点 O(n²)，合法窗口可不断尝试缩短，左端无需回退。", "invariant": "进入 while 时窗口合法，先记录长度，再丢弃左端尝试更短解。", "frames": [{"action": "a=[2,3,1,2,4,3]，target=7", "state": "读到下标3 / sum=8 / 长度4", "reason": "第一次合法，记录4。", "visual": {"kind": "array", "cells": ["2", "3", "1", "2", "4", "3"], "active": [0, 1, 2, 3], "markers": {"0": "L", "3": "R"}, "caption": "高亮表示当前关注的区间或状态；下方数字为下标。"}}, {"action": "缩左端", "state": "移走2 / sum=6", "reason": "不再合法，停止收缩，等待右侧扩展。", "visual": {"kind": "array", "cells": ["2", "3", "1", "2", "4", "3"], "active": [1, 2, 3], "markers": {"1": "L", "3": "R"}, "caption": "高亮表示当前关注的区间或状态；下方数字为下标。"}}, {"action": "读入4", "state": "sum=10，先长度4；再sum=7，长度3", "reason": "同一个右端可能对应多个合法窗口。", "visual": {"kind": "array", "cells": ["2", "3", "1", "2", "4", "3"], "active": [2, 3, 4], "markers": {"2": "L", "4": "R"}, "caption": "高亮表示当前关注的区间或状态；下方数字为下标。"}}, {"action": "读入3", "state": "收缩得到[4,3]，长度2", "reason": "再移走4后不合法，最终最短为2。", "visual": {"kind": "array", "cells": ["2", "3", "1", "2", "4", "3"], "active": [4, 5], "markers": {"4": "L", "5": "R"}, "caption": "高亮表示当前关注的区间或状态；下方数字为下标。"}}], "codeNotes": ["与最长窗口不同：合法时收缩，而不是不合法时收缩。", "先更新最短答案，再移出左端。", "无解用长度n+1作哨兵，最后转成0。"], "trap": "包含负数时，丢掉左端不一定减小和，普通窗口证明失效。", "quiz": {"question": "把这里的 while 改成 if，可能怎样？", "options": ["一定变成无限循环", "漏掉同一右端下更短的合法窗口", "没有任何变化"], "correct": 1, "why": "收缩一次并不保证已探索完最短候选。"}, "practice": [{"id": "209", "title": "长度最小的子数组", "url": "https://leetcode.cn/problems/minimum-size-subarray-sum/", "hint": "独立写出“合法时更新再收缩”的循环。"}, {"id": "862", "title": "和至少为 K 的最短子数组", "url": "https://leetcode.cn/problems/shortest-subarray-with-sum-at-least-k/", "hint": "允许负数，改用前缀和与单调队列，不直接套本模板。"}], "source": "https://leetcode.cn/discuss/post/0viNMK/", "code": "// 最短窗口 · 达到目标和\n// 使用前提：数组元素严格为正，target>0；无解返回0。\n// 状态 / 不变量：进入 while 时窗口合法，先记录长度，再丢弃左端尝试更短解。\n// 复杂度：O(n) 时间 / O(1) 空间\n\nint minWindowSum(const vector<int>& a,long long target) {\n    int left=0,best=(int)a.size()+1;long long sum=0;\n    for(int r=0;r<(int)a.size();++r) {\n        // 右端加入；正数条件保证扩大窗口时和不减。\n        sum+=a[r];\n        // 窗口合法时先记录答案，再继续寻找更短窗口。\n        while(sum>=target) {\n            best=min(best,r-left+1);\n            // 收缩可能要多次；不合法后再等待右端扩展。\n            sum-=a[left++];\n        }\n    }\n    return best==(int)a.size()+1?0:best;\n}", "contract": "数组元素严格为正，target>0；无解返回0。", "cost": "O(n) 时间 / O(1) 空间"}, {"group": 6, "template": 4, "id": "6-4", "title": "LIS · 最小尾值与二分", "problem": "最长递增子序列", "problemId": "300", "url": "https://leetcode.cn/problems/longest-increasing-subsequence/", "signal": "求严格递增子序列长度，允许跳过元素。", "naive": "先理解 O(n²) DP：f[i]=1+max(f[j])，j<i且a[j]<a[i]。再按长度压缩成最小尾值。", "invariant": "tails[len-1] 是当前前缀中长度 len 的递增子序列的最小末尾。", "frames": [{"action": "a=[3,1,2,2,4]", "state": "读3：tails=[3]", "reason": "长度1的最小末尾暂为3。", "visual": {"kind": "array", "cells": ["3"], "active": [0], "markers": {}, "caption": "tails：第i格是长度i+1的最小尾值，不一定是同一条子序列。"}}, {"action": "读1", "state": "tails=[1]", "reason": "换成更小尾值，更容易接后面的数。", "visual": {"kind": "array", "cells": ["1"], "active": [0], "markers": {}, "caption": "tails：第i格是长度i+1的最小尾值，不一定是同一条子序列。"}}, {"action": "读两个2", "state": "tails=[1,2]，再读2仍为[1,2]", "reason": "严格递增不允许相等延长。", "visual": {"kind": "array", "cells": ["1", "2"], "active": [0, 1], "markers": {}, "caption": "tails：第i格是长度i+1的最小尾值，不一定是同一条子序列。"}}, {"action": "读4", "state": "tails=[1,2,4] / 长度3", "reason": "超过所有尾值，可以扩展新长度。", "visual": {"kind": "array", "cells": ["1", "2", "4"], "active": [0, 1, 2], "markers": {}, "caption": "tails：第i格是长度i+1的最小尾值，不一定是同一条子序列。"}}], "codeNotes": ["lower_bound 找首个≥x的位置。", "替换改善尾值，不改变已有最优长度。", "需要还原具体序列时，另存前驱与尾下标。"], "trap": "不能直接输出 tails 作为原数组的一条合法子序列；各位置可能来自不同路径。", "quiz": {"question": "改成最长非降子序列，用哪个边界？", "options": ["继续用lower_bound", "把数组先排序", "upper_bound，找首个>x"], "correct": 2, "why": "相等值可以延长，应跳过所有≤x的尾值。"}, "practice": [{"id": "354", "title": "俄罗斯套娃信封问题", "url": "https://leetcode.cn/problems/russian-doll-envelopes/", "hint": "宽升序、同宽高降序，再对高度做严格LIS。"}, {"id": "673", "title": "最长递增子序列的个数", "url": "https://leetcode.cn/problems/number-of-longest-increasing-subsequence/", "hint": "还要计数，只有tails长度信息不够，先用O(n²) DP。"}], "source": "https://leetcode.cn/discuss/post/tXLS3i/", "code": "// LIS · 最小尾值与二分\n// 使用前提：求严格递增子序列长度；tails 不保证就是最终子序列。\n// 状态 / 不变量：tails[len-1] 是当前前缀中长度 len 的递增子序列的最小末尾。\n// 复杂度：O(n log n) 时间 / O(n) 空间\n\nint lisLength(const vector<int>& a) {\n    vector<int> tails;\n    for(int x:a) {\n        // 严格递增使用首个>=x的位置，相等不能延长。\n        auto it=lower_bound(tails.begin(),tails.end(),x);\n        // 大于所有已知尾值，才能增加最优长度。\n        if(it==tails.end()) tails.push_back(x);\n        // 否则改善对应长度的尾值，保留更好的延伸机会。\n        else *it=x;\n    }\n    return (int)tails.size();\n}", "contract": "求严格递增子序列长度；tails 不保证就是最终子序列。", "cost": "O(n log n) 时间 / O(n) 空间"}, {"group": 6, "template": 5, "id": "6-5", "title": "区间 DP · 最长回文子序列", "problem": "最长回文子序列", "problemId": "516", "url": "https://leetcode.cn/problems/longest-palindromic-subsequence/", "signal": "答案由区间两端的选择决定，内部是同类子问题。", "naive": "暴力删与不删有指数分支；把相同区间的最优值记下来。", "invariant": "f[l][r] 表示闭区间 s[l..r] 中最长回文子序列长度。", "frames": [{"action": "s=bbab", "state": "每个单字符 f[i][i]=1", "reason": "单字符天然回文。"}, {"action": "长度2", "state": "bb→2，ba→1，ab→1", "reason": "相等两端加2，不等丢一端。"}, {"action": "长度3", "state": "bba→2，bab→3", "reason": "内部区间已完成计算。"}, {"action": "长度4", "state": "bbab→f[1][2]+2=3", "reason": "两端b匹配，中间ba最多保留1个字符。"}], "codeNotes": ["l倒序、r正序，保证下方和左方已计算。", "两端相等，内区间结果加2。", "两端不等，只能舍弃至少一个端点，取较大值。"], "trap": "这不是最长回文子串；bbab 的最优子序列可跳过一个字符。", "quiz": {"question": "为什么不能随意按 l 从小到大填表？", "options": ["倒序能省一半空间", "依赖 f[l+1][r] 可能还没算", "数组必须倒序读"], "correct": 1, "why": "填表顺序由依赖关系决定，也可改成区间长度递增。"}, "practice": [{"id": "1312", "title": "让字符串成为回文串的最少插入次数", "url": "https://leetcode.cn/problems/minimum-insertion-steps-to-make-a-string-palindrome/", "hint": "最少插入次数等于n减最长回文子序列长度。"}, {"id": "1039", "title": "多边形三角剖分的最低得分", "url": "https://leetcode.cn/problems/minimum-score-triangulation-of-polygon/", "hint": "区间DP要枚举分割点，转移不再只看两端。"}], "source": "https://leetcode.cn/discuss/post/tXLS3i/", "code": "// 区间 DP · 最长回文子序列\n// 使用前提：返回子序列长度；字符可跳过，空串返回0。\n// 状态 / 不变量：f[l][r] 表示闭区间 s[l..r] 中最长回文子序列长度。\n// 复杂度：O(n²) 时间 / O(n²) 空间\n\nint longestPalSubseq(const string& s) {\n    int n=s.size();if(!n) return 0;\n    vector<vector<int>> f(n,vector<int>(n));\n    // 左端倒序，保证依赖的下一行已经计算。\n    for(int l=n-1;l>=0;--l) {\n        f[l][l]=1;\n        for(int r=l+1;r<n;++r) {\n            // 两端匹配时保留它们，内区间最优值加2。\n            if(s[l]==s[r]) f[l][r]=f[l+1][r-1]+2;\n            // 两端不等，舍弃左端或右端，选较优子问题。\n            else f[l][r]=max(f[l+1][r],f[l][r-1]);\n        }\n    }\n    return f[0][n-1];\n}", "contract": "返回子序列长度；字符可跳过，空串返回0。", "cost": "O(n²) 时间 / O(n²) 空间"}, {"group": 7, "template": 3, "id": "7-3", "title": "单调队列 · 滑窗最大值", "problem": "滑动窗口最大值", "problemId": "239", "url": "https://leetcode.cn/problems/sliding-window-maximum/", "signal": "固定窗口反复求最大值，要求线性处理。", "naive": "每个窗口扫描 O(nk)；较旧且不更大的元素永远输给新元素，可永久删除。", "invariant": "队列下标递增、对应值严格递减；队首是窗口最大值。", "frames": [{"action": "a=[2,1,3,2]，k=2", "state": "读2：队列[0:2]", "reason": "还未形成完整窗口。"}, {"action": "读1", "state": "队列[0:2,1:1] / 输出2", "reason": "1可能在2过期后成为答案，暂时保留。"}, {"action": "读3", "state": "0已过期，1被3支配 / 队列[2:3] / 输出3", "reason": "先清理过期，再清理队尾劣势候选。"}, {"action": "读2", "state": "队列[2:3,3:2] / 输出3", "reason": "结果[2,3,3]。"}], "codeNotes": ["队首判断下标是否离开窗口。", "队尾弹出≤新值：新值更晚过期且不小。", "同下标至多进出一次，摊还O(n)。"], "trap": "只有值没有下标，就难以正确处理过期和重复最大值。", "quiz": {"question": "两个相等最大值，为什么可以丢掉较旧的？", "options": ["相等值永远不会出窗口", "题目禁止重复", "新值一样大且更晚过期"], "correct": 2, "why": "新候选在未来所有包含旧值的窗口里都至少同样好。"}, "practice": [{"id": "1438", "title": "绝对差不超过限制的最长连续子数组", "url": "https://leetcode.cn/problems/longest-continuous-subarray-with-absolute-diff-less-than-or-equal-to-limit/", "hint": "同时维护最大、最小两个单调队列，用差值约束窗口。"}, {"id": "1696", "title": "跳跃游戏 VI", "url": "https://leetcode.cn/problems/jump-game-vi/", "hint": "队列维护可转移范围内的最大DP值。"}], "source": "https://leetcode.cn/discuss/post/mOr1u6/", "code": "// 单调队列 · 滑窗最大值\n// 使用前提：1≤k≤a.size()；队列存下标，支持负数与重复值。\n// 状态 / 不变量：队列下标递增、对应值严格递减；队首是窗口最大值。\n// 复杂度：O(n) 时间 / O(k) 空间\n\nvector<int> windowMax(const vector<int>& a,int k) {\n    deque<int> q;vector<int> ans;\n    for(int i=0;i<(int)a.size();++i) {\n        // 先清理队首已离开窗口的下标。\n        while(!q.empty()&&q.front()<=i-k) q.pop_front();\n        // 新元素不小且更晚过期，旧队尾永远不再占优。\n        while(!q.empty()&&a[q.back()]<=a[i]) q.pop_back();\n        q.push_back(i);\n        // 窗口形成后，队首对应的值就是最大值。\n        if(i>=k-1) ans.push_back(a[q.front()]);\n    }\n    return ans;\n}", "contract": "1≤k≤a.size()；队列存下标，支持负数与重复值。", "cost": "O(n) 时间 / O(k) 空间"}, {"group": 7, "template": 4, "id": "7-4", "title": "字典树 · 单词与前缀查询", "problem": "实现 Trie (前缀树)", "problemId": "208", "url": "https://leetcode.cn/problems/implement-trie-prefix-tree/", "signal": "大量字符串共享前缀，需要区分整词存在与前缀存在。", "naive": "逐个单词比较前缀会重复扫描；共享前缀的字符沿同一条路径保存。", "invariant": "节点代表一个前缀，ending 标记该前缀是否也作为完整单词插入过。", "frames": [{"action": "插入 cat", "state": "根→c→a→t，t标记ending", "reason": "相同字符位置共享节点。"}, {"action": "查询 ca", "state": "路径存在，但 ending=false", "reason": "整词 search 返回false。"}, {"action": "查询前缀 ca", "state": "路径存在，返回true", "reason": "startsWith不要求结束标记。"}, {"action": "插入 ca 再查", "state": "a节点 ending=true / search返回true", "reason": "无需新建已有路径。"}], "codeNotes": ["节点编号0是根，孩子为0表示缺失；新节点从1开始。", "只在单词末尾设置ending。", "vector扩容会使引用失效，因此不跨push_back保存元素引用。"], "trap": "不要把“走到节点”当作单词存在；前缀和完整单词是两种查询。", "quiz": {"question": "只插入 cat 后 search(ca) 是什么？", "options": ["取决于插入顺序", "false，未插入完整单词ca", "true，有路径就算"], "correct": 1, "why": "只有startsWith(ca)为true。"}, "practice": [{"id": "211", "title": "添加与搜索单词 - 数据结构设计", "url": "https://leetcode.cn/problems/design-add-and-search-words-data-structure/", "hint": "通配符 . 要枚举所有存在的孩子并回溯。"}, {"id": "212", "title": "单词搜索 II", "url": "https://leetcode.cn/problems/word-search-ii/", "hint": "网格搜索与字典树结合，用前缀剪掉无效搜索。"}], "source": "https://leetcode.cn/discuss/post/mOr1u6/", "code": "// 字典树 · 单词与前缀查询\n// 使用前提：只接受小写a-z；空串也可由该实现存储。\n// 状态 / 不变量：节点代表一个前缀，ending 标记该前缀是否也作为完整单词插入过。\n// 复杂度：每次 O(L)；空间 O(26×总字符数)\n\nstruct WordTrie {\n    vector<array<int,26>> next;vector<char> ending;\n    WordTrie() { next.push_back({});ending.push_back(false); }\n    void insert(const string& s) {\n        int u=0;\n        for(char c:s) {\n            int k=c-'a';\n            if(next[u][k]==0) {\n                // 先记录新编号，避免vector扩容造成引用失效。\n                int v=next.size();next[u][k]=v;\n                next.push_back({});ending.push_back(false);\n            }\n            u=next[u][k];\n        }\n        // 只有完整单词终点才标记，前缀路径不等于单词。\n        ending[u]=true;\n    }\n    int walk(const string& s) const {\n        int u=0;\n        for(char c:s) {u=next[u][c-'a'];if(u==0) return -1;}\n        return u;\n    }\n    // 整词查询必须同时满足路径存在与终点标记。\n    bool search(const string& s) const {int u=walk(s);return u>=0&&ending[u];}\n    bool startsWith(const string& s) const {return walk(s)>=0;}\n};", "contract": "只接受小写a-z；空串也可由该实现存储。", "cost": "每次 O(L)；空间 O(26×总字符数)"}, {"group": 10, "template": 3, "id": "10-3", "title": "树形合并 · 二叉树直径", "problem": "二叉树的直径", "problemId": "543", "url": "https://leetcode.cn/problems/diameter-of-binary-tree/", "signal": "最长树路径可在某节点合并左右两条向下链。", "naive": "对每个节点重新计算子树高度会重复；一次后序遍历同时计算返回值与全局答案。", "invariant": "返回给父节点的只能是一条链；当前节点的完整路径可以连接左右两条链。", "frames": [{"action": "树：1的孩子2、3；2的孩子4、5", "state": "4、5、3分别返回高度1", "reason": "叶节点对直径贡献0。"}, {"action": "处理2", "state": "左右高度1、1 / best=2 / 返回2", "reason": "路径4→2→5有2条边。"}, {"action": "处理1", "state": "左右高度2、1 / best=3 / 返回3", "reason": "路径4→2→1→3有3条边。"}, {"action": "结束", "state": "直径=3，根高度=3", "reason": "这次恰好相等不代表概念相同；单链有差1。"}], "codeNotes": ["先拿到left与right再更新best。", "best使用left+right，因为这是经过当前节点的边数。", "返回max+1，不能把分叉路径传给父亲。"], "trap": "如果返回left+right+1，父层可能把分叉当作单链连接，得到不存在的路径。", "quiz": {"question": "返回值和全局答案为何不同？", "options": ["只是代码风格", "为了少一个变量", "父层只能连接一条向下链，答案可在当前节点转弯"], "correct": 2, "why": "区分“可继续延伸的子问题”与“在这里完成的候选解”。"}, "practice": [{"id": "124", "title": "二叉树中的最大路径和", "url": "https://leetcode.cn/problems/binary-tree-maximum-path-sum/", "hint": "链长改为路径和，负贡献截为0，全局答案允许负数。"}, {"id": "687", "title": "最长同值路径", "url": "https://leetcode.cn/problems/longest-univalue-path/", "hint": "只有相邻节点值相等时，才允许延伸对应子链。"}], "source": "https://leetcode.cn/discuss/post/K0n2gO/", "code": "// 树形合并 · 二叉树直径\n// 使用前提：树高按节点数，直径按边数；使用已有TreeNode定义。\n// 状态 / 不变量：返回给父节点的只能是一条链；当前节点的完整路径可以连接左右两条链。\n// 复杂度：O(n) 时间 / O(树高) 栈空间\n\nint treeDiameter(TreeNode* root) {\n    int best=0;\n    function<int(TreeNode*)> height=[&](TreeNode* node) {\n        if(!node) return 0;\n        // 后序遍历先求两条可向下延伸的链高。\n        int left=height(node->left),right=height(node->right);\n        // 当前节点可以连接两条链，更新按边数定义的直径。\n        best=max(best,left+right);\n        // 给父节点只能返回一条链，不能把分叉一起传上去。\n        return max(left,right)+1;\n    };\n    height(root);return best;\n}", "contract": "树高按节点数，直径按边数；使用已有TreeNode定义。", "cost": "O(n) 时间 / O(树高) 栈空间"}, {"group": 11, "template": 2, "id": "11-2", "title": "回文子串 · 奇偶中心扩展", "problem": "最长回文子串", "problemId": "5", "url": "https://leetcode.cn/problems/longest-palindromic-substring/", "signal": "要求连续回文片段，从中心向两端对称扩展。", "naive": "枚举所有区间并逐个检查最坏 O(n³)；枚举中心后每次扩展只比较一对字符。", "invariant": "扩展时内部已经是回文，若两端相同，加入这对字符仍为回文。", "frames": [{"action": "s=cbbd", "state": "中心(0,0)得到c / best=1", "reason": "奇数回文有一个字符作为中心。"}, {"action": "中心(1,2)", "state": "两端b相同，得到bb / best=2", "reason": "偶数回文中心在两个字符之间。"}, {"action": "继续外扩至(0,3)", "state": "c不等于d，停止", "reason": "不能跳过不相等端点，题目要求连续。"}, {"action": "其余中心检查完", "state": "返回bb", "reason": "每个回文都有奇数或偶数中心，枚举不会漏。"}], "codeNotes": ["同时调用expand(i,i)与expand(i,i+1)。", "先检查边界再访问字符串。", "只更新起点长度，最后一次截取，避免循环里反复复制。"], "trap": "只枚举(i,i)会漏掉bb、abba等偶数回文；子序列问题不能用此方法。", "quiz": {"question": "abba 最长回文由哪个中心找到？", "options": ["第一个a", "最后一个a", "中间两个b之间"], "correct": 2, "why": "偶数回文没有唯一中心字符。"}, "practice": [{"id": "647", "title": "回文子串", "url": "https://leetcode.cn/problems/palindromic-substrings/", "hint": "每成功扩展一次就计数，对应一个不同位置的回文子串。"}, {"id": "516", "title": "最长回文子序列", "url": "https://leetcode.cn/problems/longest-palindromic-subsequence/", "hint": "允许跳过字符时换成区间DP，不能直接扩大中心。"}], "source": "https://leetcode.cn/discuss/post/SJFwQI/", "code": "// 回文子串 · 奇偶中心扩展\n// 使用前提：按字节比较；空串返回空串。\n// 状态 / 不变量：扩展时内部已经是回文，若两端相同，加入这对字符仍为回文。\n// 复杂度：O(n²) 时间 / O(1) 辅助空间，不含返回值\n\nstring longestPalindromeCenter(const string& s) {\n    int start=0,best=0,n=s.size();\n    auto expand=[&](int l,int r) {\n        // 先检查边界；内部已回文，只需比较新的两端。\n        while(l>=0&&r<n&&s[l]==s[r]) {\n            // 仅保存起点与长度，避免反复拷贝子串。\n            if(r-l+1>best) {start=l;best=r-l+1;}\n            --l;++r;\n        }\n    };\n    // 同时枚举奇数中心和偶数中心，防止漏掉abba。\n    for(int i=0;i<n;++i) {expand(i,i);expand(i,i+1);}\n    return s.substr(start,best);\n}", "contract": "按字节比较；空串返回空串。", "cost": "O(n²) 时间 / O(1) 辅助空间，不含返回值"}];
